"""V9: authored packaging / photonics work packages a168--a200.

All numbers in exercises are hypothetical, not foundry specifications.
The compact authoring rows hold a mechanism and an independent diagnostic.
Each row becomes two consecutive work packages, not a manufacturing recipe.
"""
import json
from pathlib import Path
ROOT = Path(__file__).resolve().parents[2]
DATA = ROOT / 'public/academy/data'
CAT = {c['id']: c for c in json.loads((DATA/'catalog.json').read_text())}
OLD_SOURCES = json.loads((DATA/'sources.json').read_text())
URL_IDS = {s['url']:s['id'] for s in OLD_SOURCES}
SOURCES=[]; SR={}; COURSES=[]; PLACES=[]; RELATED=[]
def bi(s):
    a=s.split('~'); assert len(a)==2, s; return a
def source(key,title,publisher,url,scope):
    sid=URL_IDS.get(url,'v9c-'+key); SR[key]=sid
    if url not in URL_IDS or sid.startswith('v9c-'):
        t,te=bi(title); sc,sce=bi(scope)
        SOURCES.append(dict(id=sid,title=t,titleEn=te,publisher=publisher,url=url,scope=sc,scopeEn=sce,category='packaging',sourceType='primary',accessedAt='2026-10-14',imageReuse='link-only',imageReuseEn='Link only; no source illustration reproduced.'))
        URL_IDS[url]=sid
