REFS={s['id']:s for s in OLD_SOURCES+SOURCES}
BASEPLACE=next(c['place'] for c in json.loads((DATA/'course-places.json').read_text())['courses'] if c['courseId']=='silicon-photonics')
def course(cid,focus,stage_names,rows,example,model,limits,myths,sources,related,subcategory='photonic-systems',place=None):
    """Rows: bilingual unit title | mechanism | discriminating evidence."""
    f,fe=bi(focus); ex,exe=bi(example); mo,moe=bi(model); lim,lime=bi(limits)
    if cid in {'a174','a175','a180','a183'}:
        ex+=' 此算例以 c=3.00×10^8 m/s 作教學近似。'
        exe+=' This example uses the teaching approximation c=3.00×10^8 m/s.'
    myths=[bi(x) for x in myths]; assert len(myths)>=3
    rows=[r.split('|') for r in rows.strip().splitlines() if r.strip()]
    assert len(rows)==12,(cid,len(rows)); assert all(len(r)==3 for r in rows),(cid,rows)
    src=[SR[s] for s in sources]; c=dict(CAT[cid]); c.update(status='guided',contentStatus='reviewable-educational-curriculum',curriculumVersion=9,depth=4,stepCount=24,estimatedMinutes=840,simulationOnly=True,languageCoverage=['zh-TW','en'],sourceIds=src,subcategory=subcategory)
    c['summary']=f'從{f}拆成 4 階段、24 項可保存的工程作業；包含物理模型、算例、可區分失效的量測與驗收證據。'
    c['summaryEn']=f'Four stages and 24 saveable work packages investigate {fe}, including physical models, a worked example, discriminating measurements and acceptance evidence.'
    c['scope']='公開原理的概念設計與資料判讀課，非供應商配方或可直接投產的操作程序。算例全部是教學假設；真正驗收須使用適用版本、合格設備與實測參數。代表照片、示意圖與影片不宣稱為每步製造實拍。'
    c['scopeEn']='Conceptual design and data interpretation from public principles, not a vendor recipe or production-ready procedure. All worked inputs are educational assumptions. Real acceptance requires the applicable revision, qualified equipment and measured parameters. Representative media are not claimed as footage of every operation.'
    c['workedExample']={'title':'可重算的教學算例','titleEn':'Reproducible teaching example','text':ex,'textEn':exe,'assumptions':lim,'assumptionsEn':lime,'sourceScope':'自行編寫的假想算例；原始資料支援領域原理，不提供這組假設數值。','sourceScopeEn':'Independently authored hypothetical exercise; primary sources support the field, not these chosen inputs.'}
    stages=[bi(x) for x in stage_names.split('|')]; assert len(stages)==4
    c['diagram']={'type':'photonics','labels':[s[0] for s in stages],'labelsEn':[s[1] for s in stages],'original':True,'notToScale':True}
    c['stages']=[]
    for k,(st,ste) in enumerate(stages):
        stage={'id':f'{cid}-stage{k+1:02d}','order':k+1,'title':st,'titleEn':ste,'description':f'以三個技術單元完成「{st}」的模型與驗證，六項作業各自留存交付物。','descriptionEn':f'Three technical units address {ste} through six separately saved modeling and verification work packages.','steps':[]}
        for j in range(3):
            unit=k*3+j; title,principle,evidence=map(bi,rows[unit]); p,pe=principle; ev,eve=evidence
            for mode in range(2):
                n=unit*2+mode+1; sid=f'{cid}-v9-{n:02d}'
                suffix=['模型與設計','量測與判別'][mode]; suffixen=['model and design','measurement and diagnosis'][mode]
                wrong=myths[(unit+mode)%len(myths)]; wrong2=myths[(unit+mode+1)%len(myths)]
                instruction=(f'先以師傅示意確認「{title[0]}」的輸入、輸出與座標，再在學徒工作台完成對應元件或資料流的排列。{p} 用本單元的變數畫出至少兩種設計狀態，說明它們在「{ev}」的驗證中應有何差異；把待量測參數另列，不以動畫位置當成實際公差。' if mode==0 else f'保留上一作業的模型，現在檢驗它是否足以解釋觀察。{ev} 記錄原始量、單位、基準與重複量測差異；以支持及否定各一項證據比較「{p}」與錯誤假說「{wrong[0]}」，最後提出放行、重測或修模決定。')
                instructionen=(f'Use the mentor view to identify the inputs, outputs and coordinates for {title[1].lower()}, then arrange the corresponding components or data flow in the apprentice workspace. {pe} Draw at least two design states using this unit\'s variables and predict how the following verification distinguishes them: {eve} List unmeasured parameters separately; animation positions are not manufacturing tolerances.' if mode==0 else f'Retain the previous model and test whether it explains the observations. {eve} Record raw quantities, units, reference conditions and repeatability. Use supporting and falsifying evidence to compare "{pe}" against the incorrect hypothesis "{wrong[1]}"; decide whether to accept, repeat or revise the model.')
                if unit==2:
                    instruction+=' '+ex; instructionen+=' '+exe
                correct=principle if mode==0 else evidence
                options=[correct,wrong,wrong2]; shift=(n-1)%3; options=options[-shift:]+options[:-shift] if shift else options
                objective_action = '建立可檢驗的物理模型' if mode==0 else '區分機制並作出有證據的驗收決定'
                objective_action_en = 'Build a falsifiable physical model' if mode==0 else 'Discriminate mechanisms and make an evidence-based acceptance decision'
                step=dict(id=sid,order=n,sequence=n,estimatedMinutes=35,simulationOnly=True,sourceIds=src,prerequisiteIds=[f'{cid}-v9-{n-1:02d}'] if n>1 else [],title=f'{title[0]}：{suffix}',titleEn=f'{title[1]}: {suffixen}',objective=f'以「{title[0]}」{objective_action}，交付可重算且列明邊界的工程紀錄。',objectiveEn=f'{objective_action_en} for {title[1].lower()}, with reproducible calculations and stated boundaries.',instruction=instruction,instructionEn=instructionen,observation=ev,observationEn=eve,failure=f'須排除的錯誤假說：{wrong[0]} 若觀察不支持預測，先核對基準與單位，再依本步判別量測定位原因；不能只調參到曲線相合。',failureEn=f'Incorrect hypothesis to reject: {wrong[1]} If observations disagree, first check references and units, then use this step\'s discriminating measurement; do not simply tune parameters until curves agree.',check=(f'提交{title[0]}的兩狀態模型、變數表，以及能由「{ev}」反駁模型的預測。' if mode==0 else f'提交{title[0]}的量測判別表：{ev} 附上基準、重複性或不確定度，及不能由本資料判定的結論。'),checkEn=(f'Submit two model states and a variable table for {title[1].lower()}, plus a falsifiable prediction using: {eve}' if mode==0 else f'Submit a measurement-discrimination table for {title[1].lower()}: {eve} Include the reference, repeatability or uncertainty, and conclusions the data cannot support.'),knowledge=[{'id':sid+'-k1','title':'本單元物理機制','titleEn':'Unit mechanism','text':p,'textEn':pe,'sourceIds':src},{'id':sid+'-k2','title':'獨立驗證與證據','titleEn':'Independent verification and evidence','text':ev,'textEn':eve,'sourceIds':src},{'id':sid+'-k3','title':'量化模型與適用邊界','titleEn':'Quantitative model and validity boundary','text':mo+' '+lim,'textEn':moe+' '+lime,'sourceIds':src}],quiz={'question':f'要審查「{title[0]}」，哪項主張或驗證方法有根據？','questionEn':f'Which claim or verification is justified when reviewing {title[1].lower()}?','options':[o[0] for o in options],'optionsEn':[o[1] for o in options],'answer':shift,'explanation':p+' '+ev,'explanationEn':pe+' '+eve})
                stage['steps'].append(step)
        c['stages'].append(stage)
    COURSES.append(c)
    refs=[{key:REFS[s][key] for key in ['title','titleEn','publisher','url'] if key in REFS[s]} for s in src]
    pl=dict(place or BASEPLACE)
    pl['coordinateScope']='公開機構的近似代表點；是研究／測試／供應鏈學習定位，不表示本課全部製程在此量產，也不是設備位置。'
    pl['coordinateScopeEn']='Approximate public institutional reference for research, testing or supply-chain learning; not a claim that every course process is produced here or an equipment location.'
    PLACES.append(dict(courseId=cid,place=pl,summary=f'{c["title"]}以{f}連結元件物理與系統驗證。此代表地點用於認識研究與封裝供應鏈；課程由多個公開來源交叉編寫。',summaryEn=f'{c["titleEn"]} links device physics and system validation through {fe}. This representative location illustrates the research and packaging ecosystem; the curriculum draws on several public sources.',connection=f'以{f}比較相關工法；重新核對材料、波段、控制拓撲與驗收門檻。',connectionEn=f'Compare related methods through {fe}, rechecking materials, wavelength, control topology and acceptance limits.',history=[{'year':'研究脈絡 / Research context','title':'從單元件指標到可測試系統','titleEn':'From component metrics to testable systems','text':f'本課把{f}放在材料、介面及封裝的連續證據鏈中。下列原始研究與機構資料呈現不同發展路線；此欄是教學脈絡，並非宣稱此地的發明年表。','textEn':f'This course puts {fe} within a continuous evidence chain of materials, interfaces and packaging. The primary studies and institutional records show different development routes; this is learning context, not a claimed invention timeline for this location.','sourceIds':src}],references=refs,sourceIds=src))
    rels=[]
    for rid,transfer,difference,practice in related:
        tr,tre=bi(transfer); diff,diffe=bi(difference); pr,pre=bi(practice)
        assert rid in CAT and rid!=cid
        rels.append(dict(id=rid,title=CAT[rid]['title'],titleEn=CAT[rid]['titleEn'],why=tr,whyEn=tre,transfer=tr,transferEn=tre,difference=diff,differenceEn=diffe,practice=[pr,'在兩課中各選一個能推翻結論的量測。','標出交接時不能直接沿用的材料參數或控制條件。'],practiceEn=[pre,'Choose one falsifying measurement in each course.','Identify material parameters or control conditions that cannot be transferred unchanged.'],referenceUrls=[r['url'] for r in refs]))
    assert len(rels)==2
    RELATED.append(dict(courseId=cid,overview=f'由{f}延伸到不同工法，保留物理關係並重新界定系統邊界。',overviewEn=f'Extend {fe} to related methods while retaining physical relationships and redefining system boundaries.',related=rels,references=refs))

course('a168','晶軸、電光重疊與異質界面~crystal orientation, electro-optic overlap and heterogeneous interfaces','材料與模式~Materials and modes|接合與電極~Bonding and electrodes|頻寬與熱~Bandwidth and heat|變異與放行~Variation and acceptance',r'''
晶軸與偏振~Crystal axes and polarization|鈮酸鋰的電光響應是張量；晶切面、光偏振與電場方向共同決定有效係數。~Lithium niobate has a tensor electro-optic response; cut, optical polarization and field direction determine the effective coefficient.|旋轉座標後重新投影電場與偏振，檢查是否誤把最大張量分量套到所有方向。~Rotate the coordinates and reproject field and polarization to detect misuse of the largest tensor component.
混合模態~Hybrid optical mode|光場在矽、鈮酸鋰與包覆層間分配；提高材料重疊未必降低總插損。~The optical field spans silicon, lithium niobate and cladding; more material overlap need not reduce total loss.|比較兩種截面的重疊積分與金屬吸收，保持波長及正規化功率相同。~Compare overlap integrals and metal absorption for two cross sections at fixed wavelength and normalized power.
半波電壓長度積~Half-wave voltage-length product|在同一電極與模態定義下，VπL 用來比較相移效率；長度增加會增加光與射頻損失。~At consistent electrode and mode definitions, VπL compares phase efficiency; added length also adds optical and RF loss.|用算例比較縮短電極後所需電壓；另列未計入的驅動阻抗與終端功率。~Use the worked example to compare voltage after shortening electrodes; list excluded driver impedance and termination power.
界面間隙~Interface gap|接合層厚度改變混合模態與垂直耦合，均勻平均值不能揭露局部空洞。~Bond-layer thickness changes hybrid modes and vertical coupling; a uniform mean does not reveal local voids.|把截面量測與沿線散射位置對照，區分均勻間隙偏移和局部接合缺陷。~Correlate cross sections with scattering positions to separate uniform gap shifts from local bonding defects.
漸變轉換器~Adiabatic transition|漸變長度須相對於局部模態分離判讀；幾何平滑不等於所有波長都絕熱。~Taper length must be assessed against local mode separation; smooth geometry is not adiabatic at every wavelength.|掃描波長與漸變長度，看反射或高階模功率是否隨長度收斂。~Sweep wavelength and taper length and check whether reflection or higher-mode power converges.
行波電極~Traveling-wave electrode|光群速度與射頻相速度不匹配會累積調變相消；端口反射又會造成波紋。~Optical-group and RF-phase velocity mismatch causes accumulated cancellation; port reflection adds ripple.|同時檢查 S11、S21 與電光響應，避免將電極反射誤判成材料頻寬。~Inspect S11, S21 and electro-optic response together rather than calling electrode reflection a material bandwidth.
光電速度匹配~Velocity matching|射頻有效折射率應與光群折射率比較，不是光相位折射率。~Compare RF effective index with optical group index, not optical phase index.|從射頻相位斜率與光群延遲分別萃取兩個速度，列出頻率相依性。~Extract velocities independently from RF phase slope and optical group delay, including frequency dependence.
溫升與偏壓漂移~Heating and bias drift|電極損耗與界面熱阻可移動干涉儀工作點；慢漂移不一定是 Pockels 響應。~Electrode loss and interface thermal resistance can shift interferometer bias; slow drift is not necessarily a Pockels response.|用調變頻率掃描及零平均電壓對照區分瞬時電光項與慢熱項。~Use frequency sweeps and zero-mean-voltage controls to separate fast electro-optic and slow thermal terms.
電荷遷移~Charge migration|長時間偏壓可改變局部電場；固定偏壓下的相位不是永久不變常數。~Long bias exposure can change local fields; phase at a fixed bias is not necessarily time invariant.|比較正負偏壓歷史及等待時間，記錄遲滯而不只保存最後一點。~Compare positive and negative bias histories and dwell times, retaining hysteresis rather than only final points.
接合應力~Bonding stress|異質材料熱膨脹失配能使薄膜彎曲並改變光耦合。~Thermal-expansion mismatch can bend the heterogeneous film and alter optical coupling.|將溫循前後的形貌、插損及相位分开量測，避免單一功率指標掩蓋應力。~Measure geometry, loss and phase separately before and after cycling so one power metric does not hide stress.
晶圓統計~Wafer statistics|中位數效率與尾部缺陷是不同良率風險；缺測晶粒不可當成成功樣本。~Median efficiency and tail defects pose different yield risks; missing measurements are not successful dies.|畫出位置圖、失效數及量測覆蓋率，再比較晶圓中心與邊緣。~Map positions, failures and coverage before comparing wafer center and edge.
封裝交接~Package handoff|裸晶的電光頻寬不包含連接器、接合線與熱控制；封裝驗收需要明確參考面。~Bare-die bandwidth excludes connectors, bonds and thermal control; package acceptance needs explicit reference planes.|在相同校正面比較裸晶與封裝曲線，保存去嵌入檔與偏壓條件。~Compare bare-die and packaged curves at matched calibration planes and retain de-embedding files and bias conditions.
''','教學假設 VπL=2 V·cm，L=5 mm=0.5 cm，則 Vπ=4 V；改為 2.5 mm 得 8 V。這只比較相移效率，沒有估算終端或射頻損失。~Assume VπL=2 V·cm and L=5 mm=0.5 cm, giving Vπ=4 V; 2.5 mm gives 8 V. This compares phase efficiency without termination or RF loss.','Δφ≈πV/Vπ；小訊號模型還需電光重疊與行波衰減。~Δφ≈πV/Vπ; a small-signal model also needs electro-optic overlap and traveling-wave attenuation.','電極定義、偏振及波長固定；不能把教學 VπL 視為商用品規格。~Fix electrode definition, polarization and wavelength; the teaching VπL is not a commercial specification.',['鈮酸鋰每個晶向有相同電光係數。~Lithium niobate has the same electro-optic coefficient in every direction.','只要增加電極長度就必定提高頻寬。~Increasing electrode length always increases bandwidth.','光相位折射率一定等於射頻有效折射率。~Optical phase index always equals RF effective index.'],['ln','adk'],[('a162','兩課都由差動相位產生干涉調變。~Both convert differential phase into intensity modulation.','鈮酸鋰採電光張量；矽 MZI 常用載子改變折射率，損耗與偏壓機制不同。~Lithium niobate uses an electro-optic tensor; silicon MZIs often use carriers, with different loss and bias mechanisms.','用同一長度比較相移效率與吸收預算。~Compare phase efficiency and absorption budgets at equal length.'),('a170','微轉印可把異質材料局部放到目標波導。~Micro-transfer printing places heterogeneous materials locally on target waveguides.','雷射晶粒還需要增益、電流與散熱；被動鈮酸鋰薄膜沒有雷射閾值。~Laser coupons additionally need gain, current and cooling; passive lithium-niobate films have no laser threshold.','畫出薄膜與雷射晶粒的兩種電極與熱路。~Draw separate electrode and thermal paths for a film and laser coupon.')],subcategory='heterogeneous-light-sources')

course('a169','增益模態、接合界面與雷射熱路~gain modes, bonding interfaces and laser heat paths','架構與增益~Architecture and gain|界面與耦合~Interfaces and coupling|電熱與雜訊~Electrothermal behavior and noise|可靠度與交接~Reliability and handoff',r'''
混合與異質整合~Hybrid versus heterogeneous integration|對接已製成雷射與先接合材料再製作元件，是不同的流程與良率邊界。~Attaching a completed laser and bonding material before device fabrication have different process and yield boundaries.|繪出兩條流程並標示可以做 known-good-die 檢查的位置。~Draw both flows and mark where known-good-die screening is possible.
增益與損耗~Gain and loss|雷射閾值要求受限增益補償內部及鏡面損耗；有電流並不代表達到雷射振盪。~Threshold requires confined gain to compensate internal and mirror losses; current alone does not prove lasing.|比較光功率拐點、線寬與光譜，避免只用發光照片宣稱雷射。~Compare power kink, linewidth and spectrum rather than claiming lasing from a glow image.
耦合損失~Coupling loss|III-V 模態與矽波導模態的振幅、相位及偏振都影響耦合。~Amplitude, phase and polarization of III-V and silicon modes all affect coupling.|用損耗算例建立界面預算，再檢查轉換器是否把功率散到高階模。~Build an interface budget from the loss example and check power scattered into higher modes.
接合層厚度~Bond-layer thickness|過厚間隔會削弱倏逝耦合；空洞會造成局部機械及熱失連。~A thick gap weakens evanescent coupling; voids create local mechanical and thermal discontinuity.|比較均勻厚度偏差與局部空洞的空間散射圖及熱像。~Compare spatial scattering and thermal maps for a uniform thickness error versus a local void.
對位容差~Alignment tolerance|容差應由損失曲面定義，而不是僅由機台重複定位數字決定。~Tolerance should follow a loss surface, not only the placement machine repeatability number.|畫 x、y 兩軸偏移的等損失線，加入轉角及晶粒翹曲的不確定度。~Plot x-y equal-loss contours and include rotation and die-warp uncertainty.
背反射路徑~Back-reflection paths|耦合器與封裝端面可能形成外腔，改變雷射雜訊和穩定性。~Couplers and package facets can form an external cavity and alter laser noise and stability.|在模擬中改變反射相位，檢查功率相同時線寬或相對強度雜訊是否改變。~Vary reflected phase in simulation and check linewidth or relative-intensity-noise changes at equal power.
電流展布~Current spreading|接觸電阻及電流擁擠會造成局部溫升，平均電流密度不足以描述熱點。~Contact resistance and current crowding create local heating; mean current density misses hot spots.|將電壓降與熱像位置對照，區分光學吸收和接觸發熱。~Correlate voltage drop with thermal position to distinguish absorption from contact heating.
熱阻網路~Thermal-resistance network|主動區到散熱器的路徑包含接合層、基板及接觸熱阻。~The active-region-to-sink path includes bond layer, substrate and contact resistances.|用階躍電功率比較暫態溫度與穩態溫升，辨認單一熱阻模型是否不足。~Compare transient temperature and steady rise under a power step to test a single-resistance model.
閾值溫度依賴~Temperature-dependent threshold|主動區溫度改變增益與復合；封裝外殼溫度不等於接面溫度。~Active-region temperature alters gain and recombination; case temperature is not junction temperature.|比較等外殼溫度、不同散熱條件的 L-I 曲線，保留自熱估計。~Compare L-I curves at equal case temperature but different cooling, retaining self-heating estimates.
光譜與模態跳動~Spectra and mode hopping|掃描平均光譜可能隱藏短暫模態跳動和雙峰競爭。~An averaged spectrum can hide transient mode hops and competing modes.|同步记录驅動、溫度與時間解析光譜，分開掃描方向。~Record drive, temperature and time-resolved spectra together, separating sweep directions.
老化判別~Aging discrimination|功率下降可能來自主動區退化或耦合漂移，兩者不能由單一輸出功率辨識。~Power decline may come from active-region degradation or coupling drift; output power alone cannot distinguish them.|比較閾值、斜率效率及對位掃描，必要時保留獨立監測端。~Compare threshold, slope efficiency and alignment scans, retaining an independent monitor when needed.
量產可測試性~Production testability|整合雷射後仍需可追溯的光電測試入口；封住介面前要保存基線。~An integrated laser still needs traceable optical and electrical test access; save a baseline before sealing interfaces.|設計封裝前後同參考面的測試矩陣，區分新失效與原有裸晶缺陷。~Design pre/post-package tests at matched planes to separate new failures from pre-existing die defects.
''','假設 III-V 輸出 10 mW，介面損失 1.5 dB、波導損失 0.5 dB，矽端功率=10×10^(-2/10)=6.31 mW；兩個獨立標準不確定度各 0.1 dB，總損失 u≈0.141 dB。~Assume 10 mW from III-V, 1.5 dB interface loss and 0.5 dB waveguide loss. Silicon-side power is 10×10^(-2/10)=6.31 mW. Two independent 0.1 dB standard uncertainties give u≈0.141 dB for total loss.','Pout=Pin×10^(-IL/10)；ΔT≈PheatRth 只用於線性穩態熱路。~Pout=Pin×10^(-IL/10); ΔT≈PheatRth applies only to a linear steady thermal path.','功率參考面固定、被動損失以 dB 相加；雷射回饋與非線性自熱未納入算例。~Fix power reference planes and add passive losses in dB; feedback and nonlinear self-heating are excluded.',['封裝外殼溫度永遠等於接面溫度。~Case temperature always equals junction temperature.','只見發光就能確認雷射閾值。~Visible emission alone proves lasing threshold.','功率降低一定是主動區永久損壞。~Lower output always means permanent active-region damage.'],['mprint','soa','tap'],[('a170','兩課都要控制異質模態與晶粒熱路。~Both manage heterogeneous modes and coupon heat paths.','微轉印加入供體釋放與印章轉移；接合整片材料的缺陷統計不同。~Microprinting adds donor release and stamp transfer; whole-material bonding has different defect statistics.','比較接合與微轉印的可測試節點。~Compare test-access nodes for bonding and microprinting.'),('a172','兩課共用雷射穩定性、背反射與光功率預算。~Both use laser stability, reflection and power budgets.','外接光源可置於較冷且可維修的模組；晶上接合縮短光路但耦合熱環境。~External sources can occupy cooler serviceable modules; bonded sources shorten optical paths but share the thermal environment.','比較等接收功率下的熱路與維修範圍。~Compare heat paths and service domains at equal received power.')],subcategory='heterogeneous-light-sources')

course('a170','供體晶粒、印章轉移與異質光耦合~donor coupons, stamp transfer and heterogeneous optical coupling','供體與測試~Donors and screening|拾取與轉印~Pickup and printing|接觸與光電~Contacts and optoelectronics|統計與維修~Statistics and repair',r'''
供體晶粒邊界~Donor-coupon boundary|可轉印晶粒需在源晶圓上保留支撐與釋放路徑；元件良率和釋放良率分開計算。~Printable coupons need support and release paths on the donor; device and release yields are separate.|畫出元件、錨點與犧牲層的概念截面，標明哪個測試在釋放前完成。~Draw conceptual device, tether and release-layer sections and mark tests completed before release.
已知良品分選~Known-good-coupon screening|預先量測減少把壞晶粒放到昂貴目標晶片的機會，但篩選覆蓋率不等於百分之百。~Prescreening reduces placement of bad coupons on valuable targets, but test coverage is not perfect.|用混淆矩陣列真良品、漏失效、誤拒與未測晶粒。~Build a confusion matrix of good coupons, missed defects, false rejects and untested coupons.
串接良率~Serial yield|釋放、拾取、放置與連接的成功率相乘只適用於所採獨立近似。~Release, pickup, placement and connection yields multiply only under the chosen independence approximation.|重算串接良率並比較共同污染造成的相關失效；不能以最佳單步數值代表總良率。~Recalculate serial yield and compare correlated contamination failures; best single-step yield is not total yield.
印章黏附選擇~Stamp adhesion selection|拾取與放置需要不同有效黏附條件；印章變形會改變接觸面與姿態。~Pickup and release need different effective adhesion conditions; stamp deformation changes contact area and pose.|比較印章接觸前後影像及目標位置，區分未拾取、未釋放與滑移。~Compare pre/post-contact images and target coordinates to distinguish missed pickup, failed release and slip.
錨點斷裂~Tether fracture|錨點應在預期位置分離；碎片與晶粒裂紋是不同失效證據。~Tethers should separate at intended sites; debris and coupon cracks are distinct failure evidence.|對照源位和目標位的顯微圖，保留碎片位置而不只看目標有無晶粒。~Compare donor and target micrographs, recording debris positions rather than only coupon presence.
轉印座標~Print coordinates|供體、印章與目標各自座標需經旋轉、縮放與偏移轉換。~Donor, stamp and target coordinates require rotation, scale and offset transformations.|用至少三個不共線標記擬合仿射轉換，再以未參與擬合的點驗證殘差。~Fit an affine transform from at least three noncollinear marks and validate residuals on withheld marks.
垂直與橫向耦合~Vertical and lateral coupling|高度、偏移與傾角會共同改變轉印後的模態重疊。~Height, lateral offset and tilt jointly change post-print mode overlap.|畫三個誤差軸的敏感度，對照耦合功率與散射影像，避免單軸最佳化。~Plot sensitivity on three error axes and compare coupled power with scattering images rather than optimizing one axis alone.
電接觸連續性~Electrical contact continuity|光對準成功不保證電連接；接觸電阻會增加自熱與電壓降。~Successful optical alignment does not guarantee electrical continuity; contact resistance adds heat and voltage drop.|將四線電阻與 L-I-V 量測對照，分離接觸與主動區變化。~Correlate four-wire resistance with L-I-V measurements to separate contacts from active-region changes.
晶粒熱路~Coupon thermal path|薄晶粒與接合界面使熱路高度局部化，平均基板溫度可能掩蓋熱點。~Thin coupons and bond interfaces localize heat paths; mean substrate temperature can hide hot spots.|比較不同驅動占空比的光譜漂移與暫態熱響應。~Compare spectral drift and transient thermal response at different drive duty cycles.
重工選擇~Rework choice|移除失效晶粒可能損傷目標波導或金屬；重工成功率應計入總成本。~Removing a failed coupon may damage target waveguides or metal; rework success belongs in the cost model.|列重工前後必測的光學、電學與表面項，計算目標報廢的機會成本。~List optical, electrical and surface tests before/after rework and calculate target-scrap opportunity cost.
陣列統計~Array statistics|大量轉印時位置相關誤差可能支配尾部良率；單晶粒最佳結果不能代表陣列。~Spatially correlated errors can dominate array tails; the best coupon does not represent the array.|繪 x-y 殘差向量場並比較整體偏移、縮放錯誤和隨機散布。~Plot x-y residual vectors and distinguish offset, scale error and random scatter.
追溯編碼~Traceability coding|源晶圓與目標晶片身分必須連結，才能將後續失效回溯供體批次。~Donor and target identities must be linked to trace later failure to a donor lot.|建立供體位置、測試結果、印章批次和目標位置的關聯表並做一次反查。~Link donor position, screening result, stamp batch and target position, then perform a reverse trace.
''','假設釋放、拾取、放置與連接成功率依序為 0.98、0.99、0.97、0.99，獨立模型總良率=0.9317，即約 93.2%；1000 顆的期望成功數約 932，非保證實得數。~Assume independent release, pickup, placement and connection probabilities of 0.98, 0.99, 0.97 and 0.99. Total yield is 0.9317, about 93.2%; 1,000 coupons give about 932 expected successes, not a guaranteed count.','Ytotal=∏Yi；對位殘差須在共同坐標下計算。~Ytotal=∏Yi; alignment residuals must use a common coordinate system.','獨立良率模型不含同批污染、印章磨耗與空間相關性。~The independent-yield model excludes batch contamination, stamp wear and spatial correlation.',['單一最佳晶粒可以代表整片陣列良率。~The best coupon represents full-array yield.','光對準成功即可證明所有電接點成功。~Optical alignment proves all electrical contacts are good.','總良率等於各步良率的算術平均。~Total yield is the arithmetic average of step yields.'],['mprint','ln','tap'],[('a169','兩課共用雷射的光、電、熱介面驗收。~Both accept laser optical, electrical and thermal interfaces.','微轉印額外引入印章與供體座標；整片接合的材料利用率和後製流程不同。~Microprinting adds stamp and donor coordinates; wafer bonding differs in material use and subsequent fabrication.','畫出兩路線失效能否重工的決策樹。~Draw a rework decision tree for both routes.'),('a168','兩課都可藉局部轉印增加主平台欠缺的材料功能。~Both can add missing material functions through local transfer.','雷射的熱與電流密度風險不同於鈮酸鋰薄膜相位調變。~Laser heat and current-density risks differ from lithium-niobate-film phase modulation.','比較相同目標平台上的供體預測試清單。~Compare donor prescreening lists on the same target platform.')],subcategory='heterogeneous-light-sources')

course('a171','量子點增益、異質磊晶缺陷與長期穩定性~quantum-dot gain, heteroepitaxial defects and long-term stability','材料與增益~Materials and gain|缺陷與腔體~Defects and cavities|動態與溫度~Dynamics and temperature|壽命與研究證據~Lifetime and research evidence',r'''
量子點與量子井~Dots versus wells|三維載子侷限改變能態分布；量子點並不自動消除所有非輻射復合。~Three-dimensional confinement changes the density of states; dots do not automatically remove nonradiative recombination.|比較能態示意和溫度相依發光，避免僅以名稱推定效率。~Compare state diagrams and temperature-dependent emission rather than inferring efficiency from a label.
矽上磊晶失配~Epitaxial mismatch on silicon|晶格及熱膨脹失配會引入缺陷與殘留應力，需分開討論。~Lattice and thermal-expansion mismatch introduce defects and residual stress that require separate treatment.|把冷卻後應力與晶體缺陷密度分開列在因果圖中。~Separate cooldown stress from crystal-defect density in a causal diagram.
閾值電流密度~Threshold current density|閾值電流密度由電流除以明確定義的注入面積，不能混用脊寬與光模態寬。~Threshold current density uses a defined injection area, not an interchangeable ridge or optical-mode width.|按算例換算 cm² 面積，並比較單顆與陣列面積定義。~Convert area to cm² in the example and compare single-device and array area definitions.
位錯影響~Dislocation effects|位錯可能提供非輻射復合路徑；局部點狀缺陷也可能主導特定晶粒。~Dislocations can create nonradiative paths, while localized defects may dominate individual dies.|對照缺陷位置、發光暗區與電致發光，不以平均缺陷數推斷單顆壽命。~Correlate defects, dark luminescence regions and electroluminescence instead of inferring device lifetime from mean defect count.
腔面與內部損耗~Facet and internal loss|鏡面損耗與內部吸收共同設定閾值；改變腔長同時改變熱與電路。~Mirror loss and internal absorption jointly set threshold; changing cavity length also changes thermal and electrical behavior.|比較多腔長樣本時固定材料批次與腔面條件，再辨識損耗趨勢。~Hold material batch and facet conditions fixed when comparing cavity lengths before interpreting loss trends.
基態與激發態~Ground and excited states|注入增加可能改變佔據與主導發光能態；不同峰不一定是外腔反射。~Increasing injection can change occupancy and dominant emitting states; different peaks are not always external reflections.|同步量測光譜與電流，追蹤峰的位置與強度隨溫度的演變。~Measure spectra with current and track peak position and strength versus temperature.
載子捕獲~Carrier capture|捕獲、逃逸與復合時間共同限制小訊號響應。~Capture, escape and recombination times jointly limit small-signal response.|比較頻率響應與偏壓曲線，檢查單一壽命近似何時無法擬合。~Compare frequency response and bias curves to identify where one-lifetime fitting fails.
自熱與線寬~Self-heating and linewidth|電熱耦合可改變閾值與頻率雜訊；線寬數值須附量測方法與觀測時間。~Electrothermal coupling affects threshold and frequency noise; linewidth needs a measurement method and observation time.|區分短時頻率雜訊與長時漂移，保留儀器底噪。~Separate short-time frequency noise from long-time drift and retain the instrument floor.
回饋敏感度~Feedback sensitivity|某種量子點結構的低回饋敏感度不代表所有反射率及延遲都穩定。~Low feedback sensitivity in one dot structure does not ensure stability at every reflectivity and delay.|建立反射強度、延遲及偏壓矩陣，記錄模態跳動與雜訊而不只量平均功率。~Build a reflection-strength, delay and bias matrix and record hopping and noise, not only mean power.
加速老化~Accelerated aging|壽命外推需要失效機制一致與適當模型；短時間無失效不能直接等同多年壽命。~Lifetime extrapolation needs a consistent failure mechanism and suitable model; a short failure-free run is not years of life.|列老化溫度、失效定義、截尾樣本與模型不確定度。~Record aging temperatures, failure definition, censored samples and model uncertainty.
研究與製造界線~Research versus manufacturing|單篇原始展示證明一組樣本可行，不自動證明量產成本、跨批良率或供貨。~An original demonstration establishes feasibility for sampled devices, not production cost, cross-lot yield or supply.|分欄列論文實測值、作者推估與課程假設，禁止混成同一規格。~Separate measured paper values, author projections and course assumptions rather than merging them into one specification.
系統整合驗收~System integration acceptance|增益晶片需通過熱、電與光介面，才能作為光引擎的一部分。~A gain chip must satisfy thermal, electrical and optical interfaces to serve in an engine.|用同一接收功率目標比較晶上量子點與外接雷射，包含維修與散熱。~Compare on-chip dot and external lasers at equal received-power targets, including service and cooling.
''','假設閾值電流 30 mA，注入面積 3 μm×1000 μm=3×10^-5 cm²，Jth=1000 A/cm²。若誤以 6 μm 寬換算，會得 500 A/cm²；差別來自定義，並非元件改進。~Assume threshold current 30 mA and injection area 3 μm×1000 μm=3×10^-5 cm², giving Jth=1000 A/cm². Using 6 μm width instead gives 500 A/cm²; that difference is a definition error, not device improvement.','Jth=Ith/A；閾值判定同時檢查 L-I 與光譜。~Jth=Ith/A; identify threshold from both L-I and spectra.','算例不表示任何原始論文性能；面積定義與儀器校正需一致。~The example does not represent any cited paper performance; area definition and calibration must be consistent.',['量子點會消除所有位錯造成的復合。~Quantum dots eliminate all dislocation-related recombination.','短期沒有失效即可保證多年壽命。~A short failure-free run guarantees years of life.','電流密度可以不說明注入面積。~Current density needs no injection-area definition.'],['qd','soa'],[('a169','兩課都以增益、損失與熱路評估矽上光源。~Both evaluate silicon-integrated sources through gain, loss and heat paths.','直接磊晶的缺陷控制不同於接合既成 III-V 材料的界面控制。~Direct epitaxy manages different defects from interfaces in bonded III-V material.','比較位錯與接合空洞各自的判別量測。~Compare discriminating measurements for dislocations and bond voids.'),('a173','兩課都須理解載子、增益飽和與雜訊。~Both need carriers, gain saturation and noise.','雷射需要腔內回饋超過閾值；SOA 通常避免形成自激腔。~A laser needs cavity feedback above threshold; an SOA normally avoids self-oscillation.','畫出相同增益區作雷射與放大器時的邊界差別。~Draw different boundaries when the same gain region forms a laser or amplifier.')],subcategory='heterogeneous-light-sources')

course('a172','外接連續光源、光分配與可維修性~external CW sources, optical distribution and serviceability','光源與介面~Source and interface|分配與預算~Distribution and budget|控制與熱~Control and heat|故障與維修~Faults and service',r'''
光源與調變分工~Source-modulator partition|外接雷射提供連續光，資料可在光引擎內調變；兩者的頻寬與管理責任不同。~An external laser supplies CW light while an engine may modulate data; their bandwidth and management roles differ.|畫出光源、分光、調變與接收參考面，標出哪些線承載資料。~Draw source, splitter, modulator and receiver planes and mark which paths carry data.
規格版本~Specification revision|ELSFP 是特定介面協議，不能以外形相似推定波長、偏振或功率等級互通。~ELSFP defines a particular interface; similar appearance does not prove wavelength, polarization or power-class compatibility.|將兩個假想模組的版本、光纖配置與功率等級列為相容性矩陣。~Create a compatibility matrix for two hypothetical modules including revision, fiber arrangement and power class.
分光預算~Splitter budget|理想 N 路等分損失是 10 log10 N dB，還要加入超額與連接損失。~Ideal equal N-way splitting loses 10 log10 N dB per branch, plus excess and connection loss.|按算例逐段追蹤 mW 與 dBm，禁止把總雷射功率複製到每一分支。~Track mW and dBm segment by segment in the example without copying total laser power to every branch.
偏振維持~Polarization maintenance|偏振敏感耦合器會把旋轉變成耦合損失；偏振保持光纖仍需軸向對準。~Polarization-sensitive couplers convert rotation into coupling loss; polarization-maintaining fiber still needs axis alignment.|比較旋轉角掃描與功率波动，分開偏振消光比和總光功率。~Compare rotation scans with power fluctuations, separating extinction ratio from total power.
連接器污染~Connector contamination|污染或間隙可同時增加損失與反射；提高光源功率不會消除根因。~Contamination or gaps can increase both loss and reflection; raising source power does not remove the cause.|以斷光狀態的檢查流程及校正功率量測判定維修需求。~Use a de-energized inspection workflow and calibrated power measurements to determine service needs.
回傳反射~Returned reflection|多路光分配將各支路反射帶回光源，路徑相位可能改變雷射狀態。~A distribution network returns branch reflections to the source; path phase can change laser behavior.|逐分支隔離假想反射故障，比較總損失相同時的雜訊差異。~Isolate simulated branch-reflection faults and compare noise at equal total loss.
冗餘光源~Redundant sources|兩個光源若共用電源、連接器或冷卻，仍存在共同原因失效。~Two sources sharing power, connectors or cooling retain common-cause failures.|畫最小割集，分開雷射、供電與共用光纖的失效域。~Draw minimal cut sets separating lasers, power and shared-fiber failure domains.
外殼與接面~Case and junction|光源移到較冷位置有助熱設計，但外殼溫度仍不能代替接面溫度。~A cooler source location helps thermal design, but case temperature is still not junction temperature.|比較不同風量的溫升曲線與輸出波長，標出未量到的接面熱阻。~Compare temperature and wavelength versus airflow and mark the unmeasured junction thermal resistance.
開機狀態機~Startup state machine|電存在、模組識別、互鎖有效與光輸出是不同狀態，不能以單一軟體旗標替代。~Power presence, identification, interlock validity and optical output are distinct states, not one software flag.|用紙上狀態圖注入缺模組、互鎖開路與過溫事件，確認轉入停光狀態。~Inject absent-module, open-interlock and overtemperature events into a paper state diagram and verify an emission-off transition.
遙測與校正~Telemetry and calibration|內建監測值需有校正參考面；監測二極體變化可能不同於實際輸出變化。~Telemetry needs a calibrated reference plane; monitor-diode drift may differ from real output drift.|將模組遙測與外部功率表對照，保存波長與溫度。~Compare telemetry with an external power meter while retaining wavelength and temperature.
熱插拔概念~Hot-swap concept|可維修性不代表可以在未知光狀態下裸露光纖；硬體需控制可接近發射。~Serviceability does not permit exposing fiber in an unknown optical state; hardware must control accessible emission.|在不發光的教學模型中驗證拔出偵測、停光與故障鎖存順序。~Verify removal detection, emission shutdown and fault latching in a non-emitting teaching model.
備品與恢復~Spares and restoration|換模組後必須重新核對光功率、偏振和管理相容性，不能只驗證能插入。~A replacement requires power, polarization and management compatibility checks, not only mechanical fit.|建立更換前後基線和回復測試，記錄服務中斷及降級容量。~Create pre/post-replacement baselines and restoration tests, recording interruption and degraded capacity.
''','假設光源 40 mW 經 1:4 分光，另有 1 dB 超額損失及 2 dB 連接損失；每路=40/4×10^(-3/10)=5.01 mW。四路功率總和約 20.0 mW，其餘為損失。~Assume a 40 mW source, 1:4 splitting, 1 dB excess loss and 2 dB connection loss. Each branch receives 40/4×10^(-3/10)=5.01 mW; all four total about 20.0 mW, with the remainder lost.','Pbranch=Psource/N×10^(-Lextra/10)。~Pbranch=Psource/N×10^(-Lextra/10).','假設等分、穩態和無增益；沒有把此功率宣稱安全或符合任何雷射等級。~Assume equal splitting, steady state and no gain; this power is not claimed safe or compliant with a laser class.',['每路都保有原光源完整功率。~Every branch retains full source power.','有兩個雷射就不存在共同失效。~Two lasers eliminate common-cause failure.','機械外形相同就保證光介面相容。~Matching mechanical shape guarantees optical compatibility.'],['elsfp','cpo','laser'],[('a191','兩課都要把光源、熱和維修介面納入 CPO 系統。~Both include source, heat and service interfaces in CPO systems.','外接光源課聚焦光分配與交換；CPO 還須共同配置 ASIC 與短電介面。~External-source study emphasizes distribution and replacement; CPO also places the ASIC and short electrical interfaces.','比較移除一個光源與一個光引擎的失效域。~Compare failure domains for removing one source versus one engine.'),('a195','兩課共用互鎖狀態與可接近光發射控制。~Both use interlock states and accessible-emission control.','功率傳輸效率不是安全分類依據，仍須採用適用測試條件。~Power-transfer efficiency is not a safety classification; applicable test conditions remain necessary.','把光功率預算的每個可接近端點標到互鎖圖。~Mark every accessible endpoint from the power budget on the interlock diagram.')],subcategory='heterogeneous-light-sources')


course('a173','增益壓縮、自發輻射與光電熱介面~gain compression, spontaneous emission and optoelectrothermal interfaces','增益與邊界~Gain and boundaries|整合與反射~Integration and reflection|雜訊與動態~Noise and dynamics|熱與驗收~Heat and acceptance',r'''
放大器與雷射~Amplifier versus laser|SOA 以受激放大處理輸入訊號；不希望介面反射形成非預期雷射腔。~An SOA amplifies input signals by stimulated emission; interface reflections should not create an unintended laser cavity.|比較有無輸入光時的光譜，區分寬頻 ASE 與窄頻自激峰。~Compare spectra with and without input to separate broad ASE from narrow self-oscillation peaks.
小訊號增益~Small-signal gain|增益應在同一光功率參考面與偏振定義下量測，接合損失不可忽略。~Gain needs consistent power planes and polarization; coupling losses cannot be omitted.|同時報晶片內部增益與端到端增益，保存去嵌入假設。~Report internal and end-to-end gain together, retaining de-embedding assumptions.
飽和與輸出~Saturation and output|輸入增加會耗盡可用載子，使增益壓縮；固定增益只適用弱訊號。~Increasing input depletes carriers and compresses gain; constant gain applies only to weak signals.|按算例畫線性外推，再用假想飽和曲線找出偏離區。~Plot the example's linear extrapolation, then locate deviation using a hypothetical saturation curve.
倏逝轉接~Evanescent transition|III-V 到矽的轉換器控制模態重疊與反射，不能只看末端對準。~The III-V-to-silicon transition controls modal overlap and reflection, not just endpoint alignment.|比較波長掃描與反射曲線，找出漸變不足或間隙偏移。~Compare wavelength sweeps and reflection curves for insufficient tapering or gap shifts.
端面反射~Facet reflection|往返增益若克服總損耗可能自激；單程增益合格不代表回路穩定。~Round-trip gain exceeding loss can self-oscillate; acceptable single-pass gain does not ensure loop stability.|畫最短反射回路並列每次通過的增益與損耗。~Draw the shortest reflection loop and list gain and loss for every pass.
偏振相依增益~Polarization-dependent gain|TE 與 TM 的受限增益可能不同，偏振漂移可表現為功率波動。~TE and TM confinement gain can differ; polarization drift can appear as power fluctuation.|固定總輸入功率掃偏振，將增益變化與溫度漂移分開。~Sweep polarization at fixed input power and separate gain variation from thermal drift.
ASE 頻譜~ASE spectrum|放大自發輻射增加輸出功率但不等於有用訊號，頻譜積分需要解析頻寬。~Amplified spontaneous emission adds output power but not useful signal; spectral integration requires resolution bandwidth.|量測有無訊號兩種光譜，以相同解析頻寬估计 ASE 底噪。~Measure spectra with and without signal and estimate ASE at identical resolution bandwidth.
多波長增益競爭~Wavelength gain competition|多通道共用載子庫，單一強通道可能壓低其他通道增益。~WDM channels share a carrier reservoir; one strong channel can suppress others.|加入或移除一個強通道並觀察其他通道功率與雜訊。~Add or remove one strong channel and monitor the others' power and noise.
瞬態增益恢復~Transient gain recovery|載子恢復使增益具記憶性，長串連續符號可能引起圖樣相關失真。~Carrier recovery gives gain memory, allowing pattern-dependent distortion.|比較相同平均功率但不同符號圖樣的眼圖與功率暫態。~Compare eye diagrams and power transients for patterns with equal mean power.
電流與熱~Current and heat|增加電流不保證線性增加淨增益，額外自熱也改變波段與飽和。~More current need not linearly increase net gain; heating shifts spectrum and saturation.|記錄 I-V、溫度和增益三者，分辨電流效果與熱回授。~Record I-V, temperature and gain together to separate current effects from thermal feedback.
雜訊串接~Noise cascading|補回插損不會恢復被破壞的訊雜比；SOA 本身還會加入 ASE。~Compensating loss does not restore lost signal-to-noise ratio; the SOA also adds ASE.|比較放大前後 OSNR，在相同量測頻寬下判讀。~Compare pre/post-amplifier OSNR using the same measurement bandwidth.
系統驗收~System acceptance|開關網路的淨增益、串擾與總功耗要一起驗收，不能只列零淨插損。~Accept switch-network net gain, crosstalk and total power together, not only zero net loss.|建立不同路由與通道負載下的增益、BER 及熱矩陣。~Build gain, BER and thermal matrices across routes and channel loads.
''','假設輸入 0.1 mW、SOA 小訊號增益 15 dB、後段損失 3 dB，線性估計輸出=0.1×10^(12/10)=1.585 mW；若已達飽和，此估計須下修。~Assume 0.1 mW input, 15 dB small-signal gain and 3 dB downstream loss. Linear output is 0.1×10^(12/10)=1.585 mW; saturation invalidates this extrapolation.','GdB=10log10(Psignal,out/Psignal,in)，需扣除 ASE 並固定參考面。~GdB=10log10(Psignal,out/Psignal,in), with ASE removed and reference planes fixed.','未納入增益飽和、偏振及溫度變化；總光功率不等於訊號功率。~Saturation, polarization and temperature changes are excluded; total optical power is not signal power.',['補回功率就能完全補回 OSNR。~Restoring power fully restores OSNR.','所有輸入功率都保持相同小訊號增益。~Small-signal gain holds at every input power.','ASE 全部是有用的調變訊號。~All ASE is useful modulated signal.'],['soaexperiment','mprint'],[('a169','同用 III-V 增益與矽光子耦合。~Both use III-V gain coupled to silicon photonics.','雷射刻意建立腔回饋，SOA 通常抑制自激。~Lasers intentionally use cavity feedback; SOAs normally suppress self-oscillation.','比較往返增益條件。~Compare round-trip gain conditions.'),('a176','SOA 可補償多級開關路徑損失。~SOAs can compensate multistage switch loss.','開關還需選路與隔離；補償不能消除串擾或 ASE。~Switches also need routing and isolation; gain cannot eliminate crosstalk or ASE.','把同一路由的損失及 OSNR 分別計算。~Calculate route loss and OSNR separately.')],subcategory='heterogeneous-light-sources')

course('a174','陣列光程差、成像與通道串擾~array path differences, imaging and channel crosstalk','規格與相位~Requirements and phase|陣列與星形耦合~Array and star couplers|誤差與封裝~Errors and packaging|測試與驗收~Testing and acceptance',r'''
頻率與波長格點~Frequency and wavelength grids|等頻率間隔並非嚴格等波長間隔，換算需指定中心波長。~Equal frequency spacing is not exactly equal wavelength spacing; conversion needs a center wavelength.|將三個等頻率通道換為波長，檢查是否錯用固定 nm 間距。~Convert three equally spaced frequencies to wavelengths and check misuse of fixed nm spacing.
相鄰臂光程差~Adjacent-arm path difference|AWG 利用相鄰波導臂的固定光程差形成波長相依的相位梯度。~An AWG uses fixed optical path increments between arms to create wavelength-dependent phase gradients.|畫三臂相位向量，分開物理長差與有效折射率。~Draw three arm phasors, separating physical length difference from effective index.
自由光譜範圍~Free spectral range|FSR 受群折射率及臂長差控制，不能直接用相位折射率代替。~FSR depends on group index and arm-length increment; phase index is not a direct substitute.|由算例檢查單位，並說明波長色散何時使近似失效。~Check units in the example and state when wavelength dispersion invalidates the approximation.
輸入自由傳播區~Input free-propagation region|星形區把輸入場展開到陣列，照明振幅包絡影響旁瓣。~The star region distributes input fields across the array; illumination envelopes affect sidelobes.|比較均勻與高斯陣列振幅的遠場，不只比較峰值。~Compare far fields for uniform and Gaussian arm amplitudes, not just peak intensity.
波導彎曲配置~Waveguide-bend layout|相同幾何長度未必有相同相位，彎曲及截面會改變有效折射率。~Equal geometric length need not mean equal phase; bends and cross sections affect effective index.|分開記錄直段、彎段長度與模態參數，做相位預算。~Budget straight and curved lengths with their separate modal parameters.
輸出成像~Output imaging|不同波長聚焦到不同輸出，但有限孔徑與像差造成通道交疊。~Different wavelengths focus onto different outputs, but finite aperture and aberration cause overlap.|掃描輸出平面的場分布，檢查峰位、寬度和鄰端口積分。~Scan output-plane fields for peak position, width and adjacent-port integrals.
隨機相位誤差~Random phase errors|臂間相位誤差抬高旁瓣與串擾，即使總通光率變化不大。~Inter-arm phase error raises sidelobes and crosstalk even when throughput changes little.|比較隨機與共同相位偏移；只有相對相位誤差改變理想干涉圖。~Compare random and common phase shifts; only relative phase errors change the ideal interference pattern.
溫度梯度~Temperature gradient|均勻溫升多表現為通道位移，非均勻溫升還可變形通帶。~Uniform heating often shifts channels; nonuniform heating can also distort passbands.|分別模擬整片同溫與跨陣列梯度，比較通帶位置及形狀。~Simulate uniform temperature and cross-array gradients, comparing passband position and shape.
偏振相依頻移~Polarization-dependent shift|TE 與 TM 的相位與群折射率不同，可能映射到不同通道。~TE and TM phase and group indices differ and may map to different channels.|保留兩種偏振的通帶圖與通道中心，不用平均掩蓋差異。~Retain separate polarization passbands and centers instead of averaging differences away.
插損參考~Loss reference|光纖到光纖插損含耦合器與波導，不能直接當成 AWG 核心損失。~Fiber-to-fiber loss includes couplers and routing, not only the AWG core.|用同晶片參考直波導去嵌入，列參考長度與差異。~De-embed with an on-chip reference waveguide and record length mismatches.
串擾定義~Crosstalk definition|串擾應指定入射通道、輸出端口與量測頻寬；單一最優通道不代表整顆。~Crosstalk needs input channel, output port and bandwidth definitions; the best channel is not the whole device.|量完整通道矩陣並區分鄰道、非鄰道與總串擾。~Measure the full channel matrix and separate adjacent, nonadjacent and total crosstalk.
封裝後回驗~Post-package retest|黏著與夾持應力可能移動或扭曲通道，需保存封裝前相同基線。~Adhesive and clamping stress can shift or distort channels; matched pre-package baselines are necessary.|在相同偏振與溫度下比較封裝前後全通道圖。~Compare full pre/post-package channel maps at matching polarization and temperature.
''','假設 ng=4、相鄰臂長差 ΔL=50 μm，FSRν≈c/(ngΔL)=1.50 THz；在 λ=1550 nm 附近，FSRλ≈λ²/(ngΔL)=12.0 nm。~Assume ng=4 and adjacent-arm increment ΔL=50 μm. FSRν≈c/(ngΔL)=1.50 THz; near λ=1550 nm, FSRλ≈λ²/(ngΔL)=12.0 nm.','Δφ=2πneffΔL/λ；FSR 使用群折射率。~Δφ=2πneffΔL/λ; FSR uses group index.','小波長範圍近似且忽略高階色散；不代表任何量產 AWG 尺寸。~Local-wavelength approximation neglecting higher dispersion; not a production AWG dimension.',['相位折射率一定可直接代替群折射率。~Phase index always directly replaces group index.','光纖到光纖損失全部來自 AWG 核心。~All fiber-to-fiber loss comes from the AWG core.','所有臂加相同相位必定增加串擾。~An equal phase shift on every arm necessarily increases crosstalk.'],['awg','isipp'],[('a175','兩課都做波長通道選擇及串擾驗收。~Both select wavelength channels and verify crosstalk.','AWG 依多臂干涉成像；微環依共振並通常逐環調諧。~AWGs image through multiarm interference; rings resonate and often tune individually.','比較相同通道數的熱校正自由度。~Compare thermal calibration degrees of freedom at equal channel count.'),('a189','相對相位擾動能改變多臂干涉。~Relative phase perturbations alter multiarm interference.','應力課處理材料張量與封裝載荷；AWG 課處理空間相位到通帶的映射。~The stress course treats tensors and loads; AWG study maps spatial phase to passbands.','把一張應力圖轉換成各臂相位誤差表。~Convert a stress map to an arm-phase-error table.')],subcategory='photonic-routing-control')

course('a175','環腔共振、通道格點與熱鎖定~ring resonances, channel grids and thermal locking','共振與耦合~Resonance and coupling|陣列與通道~Arrays and channels|控制與漂移~Control and drift|測試與可靠度~Tests and reliability',r'''
共振條件~Resonance condition|環內往返相位為整數 2π 時共振；環徑只是決定光程的一部分。~Resonance occurs at integer 2π round-trip phase; radius is only part of optical path length.|比較改變長度與折射率的兩個案例，確認兩者皆能移動共振。~Compare length and index changes, verifying both can move resonance.
載入與本徵 Q~Loaded and intrinsic Q|載入 Q 同時含內損與外耦合，線寬變寬不一定表示材料變差。~Loaded Q includes internal loss and external coupling; wider linewidth need not mean worse material.|由 through/drop 曲線共同擬合內損與耦合，避免只讀單一半高寬。~Fit through/drop responses together to separate intrinsic loss and coupling, rather than reading one linewidth.
線寬預算~Linewidth budget|Q=λ0/Δλ 需用一致的線寬定義；濾波頻寬應與訊號頻譜比較。~Q=λ0/Δλ needs a consistent linewidth definition; filter bandwidth must be compared with the signal spectrum.|按算例換算 pm 與 GHz，檢查訊號邊帶是否受截切。~Convert pm and GHz in the example and check clipping of signal sidebands.
臨界耦合~Critical coupling|單匯流排環在理想共振時，耦合損失與內損匹配可使 through 端深凹。~In an ideal single-bus ring, matched coupling and internal loss can produce a deep through-port notch.|比較欠耦合與過耦合的相位或 drop 證據，不能只靠凹陷深度唯一判定。~Use phase or drop evidence to compare under/overcoupling; notch depth alone is not unique.
FSR 與通道重覆~FSR and repeated channels|環共振週期重覆，帶外共振可能落到其他 WDM 通道。~Ring resonances repeat periodically; out-of-band resonances may land on other WDM channels.|畫至少兩個 FSR 的光譜與全通道配置。~Plot at least two FSRs with the full channel allocation.
多環級聯~Cascaded rings|級聯可改善選擇性，也增加損失、製程偏移與控制自由度。~Cascading improves selectivity but adds loss, process shifts and control degrees of freedom.|比較單環與雙環的通帶平坦度、總損失及校正變數。~Compare one/two-ring passband flatness, total loss and calibration variables.
熱調矩陣~Thermal tuning matrix|相鄰環的加熱器會互相影響，逐環孤立校正不一定能同時鎖定。~Neighboring heaters interact, so isolated calibration may not lock all rings together.|用單加熱器掃描建立 Δλi/ΔPj 矩陣，再測同時驅動。~Build a Δλi/ΔPj matrix from individual heater sweeps, then test simultaneous drive.
鎖定誤差信號~Lock error signal|峰值或谷值功率附近的斜率可能不足，須定義可辨方向的誤差信號。~Power slope near a maximum or minimum may be insufficient; the error signal must reveal direction.|比較左右失諧產生相同功率的歧義，加入小擾動方向判讀。~Compare equal-power ambiguity on both detuning sides and add small-dither direction information.
熱雙穩態~Thermal bistability|吸收自熱可使掃頻方向影響共振曲線，線性熱調並非全功率成立。~Absorption heating makes resonance depend on sweep direction; linear tuning does not hold at every power.|以相同掃速做正反向掃描，記錄遲滯與輸入功率。~Sweep both directions at equal speed and record hysteresis and input power.
偏振及背景~Polarization and background|偏振漏入或寄生干涉可扭曲環的線形，改變擬合 Q。~Polarization leakage and parasitic interference distort resonance lineshapes and fitted Q.|比較偏振清理與背景扣除前後的殘差，不只比較擬合 R²。~Compare fit residuals before/after polarization cleanup and background correction, not only R².
溫循重校~Thermal-cycle recalibration|封裝造成不可逆偏移時，原始加熱表可能失效；可調範圍也有上限。~Irreversible package shifts invalidate heater tables, and tuning range remains limited.|比較溫循前後的零功率共振、斜率與所需鎖定功率。~Compare zero-power resonance, tuning slope and locking power before/after cycling.
全通道放行~All-channel acceptance|平均通道偏差不能掩蓋最差通道；放行需檢查串擾與可調裕度。~Mean channel offset must not hide the worst channel; acceptance needs crosstalk and tuning margin.|輸出全通道鎖定誤差、加熱功率及最差鄰道串擾表。~Report every channel's lock error, heater power and worst adjacent-channel crosstalk.
''','假設 λ0=1550 nm、載入 Q=10000，線寬 Δλ=0.155 nm=155 pm；Δf≈cΔλ/λ²≈19.35 GHz。這不是某調變格式的自動合格門檻。~Assume λ0=1550 nm and loaded Q=10000. Linewidth is 0.155 nm=155 pm, or Δf≈cΔλ/λ²≈19.35 GHz. This is not an automatic pass limit for a modulation format.','Qloaded=λ0/Δλ；微小漂移 Δλ≈(dλ/dT)ΔT。~Qloaded=λ0/Δλ; small drift Δλ≈(dλ/dT)ΔT.','孤立共振、小範圍線性近似；濾波線形及訊號品質仍須量測。~Isolated-resonance, local-linear approximation; lineshape and signal quality still require measurement.',['凹陷越深就一定是內損越小。~A deeper notch always means lower intrinsic loss.','每個加熱器只影響自己的環。~Each heater affects only its own ring.','單一 FSR 內通過即可保證全波段無串擾。~Passing within one FSR guarantees no crosstalk across the whole spectrum.'],['wdm','thermal'],[('a174','兩課共用通道格點與串擾矩陣。~Both share channel grids and crosstalk matrices.','環有週期共振與局部熱調；AWG 由多臂相位共同成像。~Rings have periodic resonances and local tuning; AWGs image through collective arm phases.','比較溫度梯度對兩種通帶形狀的影響。~Compare temperature-gradient effects on both passbands.'),('a187','兩課都需校正熱漂移並驗證控制穩定性。~Both calibrate thermal drift and verify control stability.','環鎖定對象是共振波長；一般光路還可能需要相位或群延遲鎖定。~Ring control locks resonance wavelength; general paths may need phase or group-delay locking.','由環頻移建立一個有飽和限制的控制例。~Build a bounded-control example from ring wavelength drift.')],subcategory='photonic-routing-control')

course('a176','開關拓撲、損失串接與可觀測性~switch topology, cascaded loss and observability','路由與單元~Routes and units|級聯與干擾~Cascades and interference|校正與控制~Calibration and control|故障與驗收~Faults and acceptance',r'''
非阻塞定義~Nonblocking definitions|嚴格非阻塞與可重排非阻塞不同；後者可能需改變既有連線。~Strictly nonblocking and rearrangeably nonblocking differ; the latter may need existing connections changed.|用四埠圖列兩種需求，檢查新連線是否迫使舊路由搬移。~Use a four-port graph to test whether a new connection forces an existing route to move.
MZI 二態~MZI bar and cross states|兩臂相位差控制 bar/cross 功率，但耦合器不平衡限制消光比。~Differential phase controls bar/cross power, while coupler imbalance limits extinction.|同時量兩輸出並驗證總功率，分離吸收與功率轉移。~Measure both outputs and power balance to separate absorption from redistribution.
級聯損失~Cascaded loss|多級路由的插損以 dB 加總，短路徑未必有最少交叉或最低損失。~Route losses add in dB; the shortest geometric route need not have fewest crossings or lowest loss.|按算例比較跳數與損失，保存每元件損失來源。~Compare hop count and loss in the example and retain per-element sources.
交叉串擾~Crossing crosstalk|多個弱漏光可能相干相加，總串擾不一定是功率簡單相加。~Weak leakage paths can add coherently; total crosstalk is not always a simple power sum.|比較同相、反相與隨機相位的漏光合成界限。~Compare in-phase, opposite-phase and random-phase leakage bounds.
廣播與獨占~Broadcast versus exclusive routing|分光廣播與一對一路由有不同功率和容量約束。~Split broadcast and one-to-one routing have different power and capacity constraints.|在同一輸入功率下比較單輸出與雙輸出功率預算。~Compare single-output and dual-output budgets at equal input power.
波長及偏振範圍~Wavelength and polarization range|在一個波長校正的開關，不保證整個波段及偏振都保持消光。~A switch calibrated at one wavelength need not retain extinction over all wavelengths and polarizations.|量 bar/cross 的二維波長與偏振矩陣。~Measure a wavelength-polarization matrix for both bar and cross states.
監測埠配置~Monitor placement|監測點太少可能使多個錯誤狀態有相同輸出，造成不可觀測。~Too few monitors can make distinct erroneous states produce identical outputs and become unobservable.|畫每個可疑單元到監測埠的路徑，找出无法區分的一對故障。~Trace suspect units to monitors and find an indistinguishable fault pair.
熱串擾校正~Thermal-crosstalk calibration|調整一個相移器可擾動鄰居，校正順序可能影響最終狀態。~Tuning one phase shifter can disturb neighbors, making calibration order matter.|比較單次逐點校正與迭代矩陣補償的殘差。~Compare one-pass sequential tuning with iterative matrix compensation residuals.
切換暫態~Switching transient|穩態低損失不代表切換期間沒有誤送或短暫掉光。~Low steady-state loss does not exclude transient misrouting or power loss.|畫命令、光功率與有效資料時間線，定義保護間隔。~Plot command, optical-power and valid-data timelines and define a guard interval.
單元失效~Unit failure|卡在 bar、卡在 cross、額外吸收與加熱器斷路會造成不同拓撲後果。~Stuck-bar, stuck-cross, excess loss and open heaters affect topology differently.|逐類移除或固定單元狀態，重新檢查可達端口。~Remove or fix each fault type and recheck reachable ports.
控制能源~Control energy|靜態保持功率與每次切換能量是不同指標，不能只報其中較好者。~Static holding power and switching energy are different metrics and cannot be selectively substituted.|以固定路由保持及頻繁切換兩種工作負載比較總能耗。~Compare total energy for fixed-route holding and frequent-switching workloads.
抽測覆蓋~Sampled test coverage|大型開關路由組合極多，抽測需說明覆蓋和未測狀態風險。~Large switches have many route combinations; sampled tests need explicit coverage and untested-state risks.|選最長、最短、最大共用及相鄰高負載路徑，說明選樣理由。~Select longest, shortest, most shared and heavily loaded adjacent routes and justify coverage.
''','假設一路經 6 個開關各 0.4 dB、4 個交叉各 0.05 dB、波導共 0.6 dB，總損失=3.2 dB；1 mW 輸入輸出約 0.479 mW。~Assume six switches at 0.4 dB each, four crossings at 0.05 dB each and 0.6 dB routing loss. Total loss is 3.2 dB; 1 mW input gives about 0.479 mW.','ILroute=ΣILi；可達性與光功率裕度必須同時成立。~ILroute=ΣILi; reachability and optical-power margin must both hold.','假設被動損失、無相干反射與增益；數字是教學工作負載。~Assume passive loss without coherent reflections or gain; values describe a teaching workload.',['可重排非阻塞表示永不需要改變舊路由。~Rearrangeably nonblocking means old routes never change.','最短幾何路徑一定最低光損。~The shortest geometric route always has the least loss.','穩態通過就能證明切換無瞬間錯送。~Steady-state success proves no transient misrouting.'],['switch','mesh'],[('a188','共用路由圖、失效模型與容量檢查。~Both use routing graphs, fault models and capacity checks.','開關課先建立正常控制；重路由課評估失效後的可達性、容量及熱裕度。~Switch study establishes normal control; rerouting evaluates post-fault reachability, capacity and thermal margin.','對同一四埠圖做一個單元失效演練。~Exercise one unit failure on the same four-port graph.'),('a173','多級插損可引入放大器補償。~Amplifiers may compensate multistage insertion loss.','SOA 增加 ASE、飽和及熱負載，不能當成理想負損失。~An SOA adds ASE, saturation and heat and is not ideal negative loss.','比較加放大器前後的功率和 OSNR。~Compare power and OSNR before and after amplification.')],subcategory='photonic-routing-control')

course('a177','可調干涉單元、矩陣分解與閉迴路校正~tunable interferometers, matrix decomposition and closed-loop calibration','網格與模型~Mesh and model|校正與編譯~Calibration and compilation|雜訊與誤差~Noise and errors|任務與驗收~Tasks and acceptance',r'''
複數場表示~Complex-field representation|光子線性網路作用於複數場，功率只保留振幅平方而失去相位。~Linear photonic networks act on complex fields; power retains squared amplitude but loses phase.|比較等功率、不同相位的兩組輸入干涉結果。~Compare interference for two inputs with equal powers but different phases.
可調二埠單元~Tunable two-port unit|理想 MZI 可控制耦合與相位，實際不平衡限制可達矩陣集合。~An ideal MZI controls coupling and phase; imbalance limits reachable matrices.|掃描兩控制量，畫可達透射與相位範圍。~Sweep both controls and plot reachable transmission and phase ranges.
級聯矩陣~Cascaded matrices|矩陣乘法順序對應光路次序，一般不可交換。~Matrix multiplication order follows optical propagation and is generally noncommutative.|用兩個不同 2×2 矩陣驗證 AB 與 BA，再依算例檢查損失。~Compare AB and BA for two distinct 2×2 matrices, then check loss with the example.
相位電壓表~Phase-voltage table|加熱器電功率與相位並非必然線性對電壓，電阻還會隨溫度變化。~Heater phase is not necessarily linear in voltage, and resistance may vary with temperature.|記錄 I-V 與光相位，比較以 V、V² 和實測 VI 擬合。~Record I-V and phase and compare fits against V, V² and measured VI.
局部與全域校正~Local and global calibration|局部單元校正無法自動補償串接後的共同熱擾動與相位規約。~Local calibration does not automatically compensate shared heat or phase conventions after cascading.|比較逐單元預測與整體傳輸矩陣，定位系統性殘差。~Compare unit predictions with the full transfer matrix to locate systematic residuals.
目標編譯~Target compilation|所需算子可能含非酉增益或衰減，不能直接假設無損網格都可實現。~A target operator may include nonunitary gain or attenuation and need not fit a lossless mesh.|檢查目標的奇異值，再標示額外衰減或正規化需求。~Inspect target singular values and mark required attenuation or normalization.
相位規約~Phase convention|端口參考面的任意共同相位不影響某些功率任務，但會影響相干串接解讀。~A common phase at a reference plane may not affect power tasks but matters for coherent composition.|在固定規約下比對複數矩陣，避免把可忽略全域相位當元件故障。~Compare complex matrices under a fixed convention rather than treating irrelevant global phase as failure.
熱矩陣條件數~Thermal-matrix conditioning|高度相關的控制作用可能使反算對噪聲敏感。~Highly correlated actuator effects can make inversion noise sensitive.|對熱耦合矩陣加入小量測誤差，檢查求得控制量的變化。~Perturb a thermal-coupling matrix by measurement error and inspect the resulting control changes.
監測可觀測性~Monitor observability|只看單一輸出強度通常不足以重建全部複數網路。~One output intensity generally cannot reconstruct an entire complex network.|設計多組已知輸入或參考干涉量測，列出仍存在的相位歧義。~Design multiple known inputs or reference-interference measurements and list remaining phase ambiguities.
演算法收斂~Algorithm convergence|最佳化收斂到局部極值不代表全域最佳，也不保證對漂移穩健。~Convergence to a local optimum proves neither global optimality nor drift robustness.|用不同初始值及保留測試輸入比較結果，避免只驗訓練點。~Compare different initializations and held-out test inputs, not only training points.
編程後漂移~Post-programming drift|周圍負載改變可移動已編程相位，需要偵測與重校策略。~Changing surrounding load can shift programmed phases and require detection and recalibration.|注入鄰近熱源後追蹤矩陣誤差及恢復時間。~Inject neighboring heat and track matrix error and recovery time.
任務層驗收~Task-level acceptance|矩陣誤差、輸出訊雜比與任務誤差須分開報告。~Matrix error, output SNR and task error require separate reporting.|比較同一網格的路由與濾波任務，列對各任務最敏感的誤差。~Compare routing and filtering on the same mesh and identify each task's most sensitive errors.
''','假設 8 級單元各有 0.25 dB 損失，總損失 2 dB，輸出功率比例 10^(-2/10)=0.631；因此理想酉矩陣的功率守恆不能直接用於此實體網格。~Assume eight stages each lose 0.25 dB. Total loss is 2 dB and transmitted power fraction is 10^(-2/10)=0.631; ideal unitary power conservation cannot be directly assigned to this physical mesh.','Eout=TEin；檢驗 T†T 是否接近所採無損模型，而非先假設等於 I。~Eout=TEin; test whether T†T approaches the chosen lossless model rather than assuming I.','矩陣模型限於線性相干操作；非線性與動態熱記憶需擴充。~The matrix model assumes linear coherent operation; nonlinearity and dynamic thermal memory require extensions.',['只量一個輸出功率就能重建所有複數相位。~One output power reconstructs every complex phase.','任何實體網格都完全無損且酉。~Every physical mesh is lossless and unitary.','局部極值一定是全域最優。~A local optimum is necessarily global.'],['mesh','switch'],[('a176','可調 MZI 單元同時支援路由與可編程運算。~Tunable MZIs support both routing and programmable operations.','矩陣任務需要振幅和相位；二態路由的驗收可能只看端口功率。~Matrix tasks need amplitude and phase; binary routing may be accepted by port powers.','用同一 2×2 單元分別完成交換與干涉算子。~Use one 2×2 unit for switching and an interference operator.'),('a188','網格備用通路可以用來避開失效單元。~Mesh spare paths can avoid failed units.','保留連通不保證保留任意矩陣可實現性。~Maintaining connectivity does not preserve every target matrix.','失去一個單元後重新檢查目標算子而非只查連通。~After losing a unit, recheck the target operator as well as connectivity.')],subcategory='photonic-routing-control')

course('a178','光混頻、平衡偵測與光電共同設計~optical mixing, balanced detection and optoelectronic co-design','訊號與本振~Signal and local oscillator|混頻與偵測~Mixing and detection|類比與數位~Analog and digital|測試與封裝~Testing and packaging',r'''
相干接收邊界~Coherent-receiver boundary|相干接收用本振將訊號場轉成可量測差頻，不是只量總光功率。~Coherent reception mixes signal and LO fields into measurable beat signals, not only total power.|畫訊號、本振與 I/Q 輸出，標出頻率差與相位。~Draw signal, LO and I/Q outputs, marking frequency difference and phase.
本振線寬~LO linewidth|訊號與本振相對相位雜訊共同影響載波恢復。~Relative signal/LO phase noise affects carrier recovery.|固定接收功率，比較兩種相位雜訊軌跡的星座圖。~At fixed received power, compare constellations for two phase-noise trajectories.
平衡光電流~Balanced photocurrent|理想平衡偵測抵銷共同直流項並保留拍頻交叉項。~Ideal balanced detection cancels common DC terms while retaining the beat cross term.|按算例核對響應度、mW 轉 W 及兩支路電流方向。~Check responsivity, mW-to-W conversion and branch-current signs in the example.
九十度混合器~Ninety-degree hybrid|I/Q 路徑需要近正交相位，振幅與相位不平衡會拉伸或旋轉星座。~I/Q paths need near-quadrature phase; amplitude and phase imbalance distort constellations.|用已知相位掃描萃取 I/Q 不平衡矩陣。~Extract an I/Q imbalance matrix from a known phase sweep.
偏振分集~Polarization diversity|輸入偏振可隨通道改變，雙偏振接收需把兩分量送到對應混合器。~Channel polarization can vary; dual-polarization reception routes both components to corresponding hybrids.|旋轉輸入偏振，檢查總接收效率與各分支均衡需求。~Rotate input polarization and inspect total reception efficiency and branch equalization.
偵測器匹配~Detector matching|響應度、電容與延遲不匹配會降低共同模式抑制。~Responsivity, capacitance and delay mismatch reduce common-mode rejection.|施加共同光功率擾動，量差動漏出對頻率的變化。~Apply common optical-power modulation and measure differential leakage versus frequency.
TIA 噪聲與飽和~TIA noise and saturation|較強本振可改善某些噪聲比，但可能使偵測器或 TIA 飽和。~A stronger LO can improve some noise ratios but saturate detectors or the TIA.|掃 LO 功率，並列輸出噪聲、增益壓縮與 BER。~Sweep LO power and report noise, gain compression and BER together.
封裝寄生~Package parasitics|接合和焊墊寄生增加頻率相依失真，裸晶頻寬不等於完整接收頻寬。~Bond and pad parasitics add frequency-dependent distortion; die bandwidth differs from full-receiver bandwidth.|以一致校正面量電路 S 參數並與電光響應交叉驗證。~Measure circuit S-parameters at consistent planes and cross-check electro-optic response.
採樣與混疊~Sampling and aliasing|ADC 採樣率、類比頻寬及反混疊共同決定可恢復訊號。~ADC rate, analog bandwidth and antialiasing jointly determine recoverable signals.|將訊號與雜訊頻譜折疊到取樣頻帶，辨識不可逆混疊。~Fold signal and noise spectra into the sampled band and identify irreversible aliasing.
載波與定時恢復~Carrier and timing recovery|頻偏、相位與時序估計有不同時間尺度，錯誤會形成不同星座軌跡。~Frequency, phase and timing estimators operate on different scales and leave different constellation trajectories.|分別注入頻偏、相位跳變與取樣偏移，對照誤差特徵。~Inject frequency offset, phase jumps and sampling offset separately and compare signatures.
OSNR 與 BER~OSNR and BER|OSNR 必須附參考頻寬；相同 OSNR 不保證不同調變及 DSP 的 BER 相同。~OSNR requires reference bandwidth; equal OSNR does not imply equal BER across formats and DSP.|建立同格式、同頻寬 BER 對 OSNR 曲線並列置信區間。~Build a BER-versus-OSNR curve at fixed format and bandwidth with confidence intervals.
封裝測試角落~Packaged test corners|溫度、偏振、本振功率及電源共同決定最差接收狀態。~Temperature, polarization, LO power and supply jointly determine worst reception.|選擇會同時壓縮動態範圍的角落並記錄失鎖與恢復。~Choose corners that jointly squeeze dynamic range and record lock loss and recovery.
''','假設單一 50:50 平衡混頻器的入口功率（已扣除 I/Q 分支分光）為 Ps=0.01 mW、Plo=1 mW，響應度 R=0.8 A/W；差動拍頻峰值 i=2R√(PsPlo)=0.16 mA。Ps、Plo 並非整個 90° 混合器分光前的總功率。~Assume inputs of one ideal 50:50 balanced mixer, after any I/Q branch splitting: Ps=0.01 mW, Plo=1 mW and responsivity R=0.8 A/W. Differential beat amplitude i=2R√(PsPlo)=0.16 mA. These are not total powers before a full 90-degree hybrid splits them.','拍頻項正比 √(PsPlo)，量測須明確指定混合器端口功率。~The beat term scales with √(PsPlo); explicitly define hybrid-port powers.','理想匹配、無飽和、未含散粒與 TIA 噪聲；非靈敏度保證。~Ideal matching without saturation, shot noise or TIA noise; not a sensitivity guarantee.',['本振功率越大永遠越好。~More LO power is always better.','相同 OSNR 對所有調變有相同 BER。~Equal OSNR gives equal BER for every format.','平衡偵測會消除所有噪聲。~Balanced detection removes all noise.'],['coherent','tap'],[('a180','FMCW 光達也量測訊號與本振的拍頻。~FMCW lidar also measures signal-LO beats.','通訊解碼資料符號；光達由拍頻估距並分離都卜勒。~Communications decode symbols; lidar infers range and separates Doppler.','用同一混頻圖標示資料頻寬與量距頻寬。~Mark data and ranging bandwidths on one mixing diagram.'),('a193','接收器性能取決於 PIC、TIA、封裝及數位協同。~Receiver performance couples PIC, TIA, packaging and digital functions.','接收器課聚焦 I/Q 訊號鏈；共同設計還需端到端能源與可測試性。~Receiver study focuses on I/Q chains; co-design also needs end-to-end energy and testability.','把偵測器電容加入 TIA 模型再重估頻寬。~Add detector capacitance to the TIA model and reassess bandwidth.')],subcategory='photonic-sensing-computing')

course('a179','陣列相位、遠場旁瓣與封裝校正~array phase, far-field sidelobes and package calibration','場與孔徑~Fields and aperture|饋光與天線~Feed and antennas|相位與掃描~Phase and scanning|封裝與驗收~Packaging and acceptance',r'''
陣列因子~Array factor|遠場是各天線複數場相加，不能將強度直接相加來預測主瓣。~Far fields sum complex antenna fields, not intensities, to form the main lobe.|比較兩天線同相與反相遠場，維持相同總輸入功率。~Compare in-phase and opposite-phase two-antenna far fields at equal input power.
孔徑與解析度~Aperture and resolution|更大有效孔徑可縮窄主瓣，但天線包絡與照明分布仍限制性能。~A larger effective aperture narrows the main lobe, but element patterns and illumination still constrain performance.|分開畫陣列因子與單天線包絡，再相乘比較。~Plot array factor and element pattern separately before combining them.
相位梯度~Phase gradient|鄰天線相位梯度與間距共同決定掃描方向。~Adjacent phase gradient and spacing jointly set beam direction.|按算例檢查弧度與角度，並保持相位與觀察方向符號規約一致。~Check radians and degrees in the example with a consistent phase/direction sign convention.
光柵瓣~Grating lobes|規則過大間距可能形成多個可見主峰，增天線數不自動消除。~Excessive periodic spacing can create multiple visible peaks; adding elements does not remove them automatically.|掃間距並畫完整角域，不只截取預定主瓣附近。~Sweep spacing and plot the full angular domain, not only the intended lobe.
天線近場串擾~Near-field antenna coupling|緊密間距可降低光柵瓣風險卻增加相鄰導波耦合。~Tight spacing can reduce grating-lobe risk while increasing adjacent guided coupling.|比較單天線激發的鄰線功率與陣列遠場，拆開兩種效應。~Compare neighboring-line power under single-element excitation with far fields to separate effects.
振幅加權~Amplitude apodization|降低旁瓣的加權通常犧牲主瓣寬度或峰值，並不免費改善所有指標。~Sidelobe-reducing apodization usually costs beamwidth or peak intensity.|在相同總功率下比較均勻與加窗權重的主瓣、旁瓣和包圍能量。~At equal total power, compare uniform/windowed beamwidth, sidelobes and encircled energy.
熱相位校正~Thermal phase calibration|相移器控制需包含熱串擾；獨立設定值可能被鄰路改變。~Phase control must include thermal crosstalk; neighbors can alter independent setpoints.|量相位-功率矩陣並以全陣列同時驅動回驗。~Measure the phase-power matrix and retest with all elements driven.
波長掃描~Wavelength steering|光柵發射角與波長相關，改波長可能同時改兩軸指向與效率。~Grating emission angle varies with wavelength; tuning can change two-axis direction and efficiency together.|建立波長、相位梯度到兩角度及光功率的查表。~Map wavelength and phase gradient to two angles and emitted power.
相位量化~Phase quantization|有限 DAC 位元與非線性會形成相位誤差與旁瓣底。~Finite DAC resolution and nonlinearity create phase errors and sidelobe floors.|比較理想連續相位與量化相位的遠場差異。~Compare far fields from continuous and quantized phases.
封裝位姿~Package pose|晶片或透鏡整體傾斜改變外部座標零點，不一定是片上相位錯誤。~Chip or lens tilt changes the external coordinate zero and need not be on-chip phase error.|用固定外部基準分開估計剛體傾斜與各通道相位殘差。~Use an external reference to separate rigid tilt from channel-phase residuals.
近遠場轉換~Near-to-far transformation|量測距離須滿足採用的遠場近似，否則角度與光斑解讀有偏差。~Measurement distance must satisfy the chosen far-field approximation or angle/spot interpretation is biased.|比較不同觀察距離的正規化光斑，或明示透鏡傅立葉平面。~Compare normalized spots at different distances or explicitly identify a lens Fourier plane.
掃描包絡驗收~Scan-envelope acceptance|單一正前方最佳光束不能代表整個掃描範圍。~The best broadside beam does not represent the full scan range.|在邊角與溫度角落量主瓣、旁瓣及有效發射功率。~Measure main lobe, sidelobes and useful emitted power at scan and temperature corners.
''','假設均勻陣列 d=λ/2，欲偏轉 θ=30°，在所定符號下相鄰相位增量幅值 |Δφ|=2π(d/λ)sinθ=π/2；符號決定左右方向。~Assume a uniform array with d=λ/2 and θ=30°. The adjacent phase-step magnitude is |Δφ|=2π(d/λ)sinθ=π/2; its sign sets left versus right under the chosen convention.','AF(θ)=Σan exp[i(nkd sinθ+φn)]；實際遠場另乘天線包絡。~AF(θ)=Σan exp[i(nkd sinθ+φn)]; actual far field also includes the element pattern.','均勻直線陣列、遠場、忽略互耦；不是眼安全或最大量距模型。~Uniform linear array in the far field, neglecting mutual coupling; not an eye-safety or maximum-range model.',['增天線數必定消除間距造成的光柵瓣。~Adding antennas always removes spacing-induced grating lobes.','只要相加各天線強度就能算干涉主瓣。~Adding antenna intensities predicts the interference main lobe.','降低旁瓣完全不影響主瓣與效率。~Reducing sidelobes never affects main lobe or efficiency.'],['opa','thermal'],[('a180','OPA 可作 FMCW 光達的可控發射孔徑。~An OPA can provide the controllable FMCW lidar transmit aperture.','相位陣列控制方向；距離還需啁啾、混頻與時間基準。~The array controls direction; distance additionally needs chirp, mixing and timing.','把角度校正與距離校正分成兩份證據。~Separate angle-calibration and range-calibration evidence.'),('a177','兩課共用多通道相位校正及熱矩陣。~Both use multichannel phase calibration and thermal matrices.','OPA 輸出自由空間場；網格輸出導波端口算子。~OPAs output free-space fields; meshes output guided-port operators.','比較兩種系統失去一個相移器的可恢復性。~Compare recovery after one phase-shifter failure.')],subcategory='photonic-sensing-computing')

course('a180','線性啁啾、相干拍頻與距速分離~linear chirps, coherent beats and range-velocity separation','架構與啁啾~Architecture and chirp|發射與接收~Transmit and receive|估計與誤差~Estimation and errors|場景與驗收~Scenes and acceptance',r'''
往返延遲~Round-trip delay|反射量距有往返時間 τ=2R/c，不能把單程延遲套到距離公式。~Reflective ranging has round-trip delay τ=2R/c; a one-way delay cannot replace it.|畫發射、目標及回波時間線並標出兩段傳播。~Draw transmit-target-return timelines with both propagation segments.
啁啾斜率~Chirp slope|FMCW 以瞬時頻率斜率把延遲轉為拍頻，非線性啁啾會展寬或偏移距離峰。~FMCW maps delay to beat frequency through instantaneous chirp slope; nonlinearity broadens or biases range peaks.|比較理想直線與波紋啁啾經同一延遲的差頻。~Compare beats for linear and rippled chirps under the same delay.
拍頻算距~Beat-frequency ranging|靜止單目標時 fb≈2SR/c；運動目標還含都卜勒項。~For one static target fb≈2SR/c; moving targets add Doppler.|按算例計算拍頻並明示何時不能只用單一上掃估距。~Calculate the example beat and state when a single up-chirp cannot isolate range.
距離解析度~Range resolution|理想距離解析度約 c/(2B)，而最大無歧義距離還受採樣與斜率限制。~Ideal range resolution is about c/(2B), while unambiguous range also depends on sampling and slope.|分別改帶寬與掃描時間，區分解析度與最大可量距離。~Vary bandwidth and sweep time separately to distinguish resolution from maximum range.
本振分光~LO splitting|分配更多光給本振會減少發射光，需共同評估接收噪聲與目標回波。~More LO allocation reduces transmit power and requires joint noise/return budgeting.|在固定總光功率下比較三種分光比的回波與混頻電流。~Compare returned power and beat current for three split ratios at fixed total power.
發射接收重疊~Transmit-receive overlap|雙軸收發的幾何重疊隨距離改變，近距盲區不一定是感測器失效。~Biaxial transmit/receive overlap changes with range; a near blind zone need not be detector failure.|畫不同距離的光束與接收視場交集。~Draw beam-receiver-field overlaps at several ranges.
都卜勒分離~Doppler separation|上、下掃拍頻須使用一致符號規約，才能分離延遲與速度。~Up/down beats need a consistent sign convention to separate delay and velocity.|以已知正負速度的假想目標驗證估計符號，勿只保留拍頻絕對值。~Test signs with hypothetical positive/negative velocities rather than retaining only absolute beat values.
相干長度~Coherence length|雷射相位雜訊會隨延遲影響拍頻品質；平均功率相同不能保證同樣量距。~Laser phase noise degrades beats with delay; equal average power does not ensure equal ranging.|在相同回波功率下掃延遲，比較峰寬與估計方差。~Sweep delay at fixed return power and compare peak width and estimator variance.
FFT 視窗~FFT windows|窗函數在旁瓣抑制與主瓣寬度間取捨，頻率格點不等於真实解析度。~Windows trade sidelobe suppression against main-lobe width; FFT bin spacing is not true resolution.|用兩個鄰近目標比較矩形與加窗頻譜，明示補零只插值。~Compare rectangular/windowed spectra for two close targets and note that zero-padding only interpolates.
多徑與散斑~Multipath and speckle|多個反射路徑可形成額外峰與相干消光，不宜把所有峰視為獨立實體。~Multiple paths can create extra peaks and coherent fading; every peak is not an independent object.|比較移動視角或波長前後峰的穩定性並保留原始資料。~Compare peak stability after changing viewpoint or wavelength and retain raw data.
標定與時間基準~Calibration and timing|啁啾斜率及採樣時鐘誤差都會造成尺度偏差。~Chirp-slope and sample-clock errors both cause scale bias.|以兩個已知距離估斜率與偏移，再用第三個距離驗證。~Estimate scale and offset from two known ranges and validate with a third.
系統放行~System acceptance|量距、角度、速度、漏檢和誤報需分開評估，單一漂亮點雲不足。~Range, angle, velocity, misses and false alarms need separate evaluation; one attractive point cloud is insufficient.|建立反射率、距離、速度及環境光矩陣，報告失敗樣本。~Build reflectivity, range, velocity and ambient-light matrices and report failed cases.
''','假設 B=10 GHz、T=100 μs，斜率 S=10^14 Hz/s；靜止目標 R=15 m，fb=2SR/c≈10 MHz。理想解析度 c/(2B)=15 mm；不含窗函數及雜訊。~Assume B=10 GHz and T=100 μs, giving S=10^14 Hz/s. A static target at R=15 m gives fb≈10 MHz. Ideal resolution c/(2B)=15 mm, excluding window and noise effects.','R≈cfb/(2S) 僅對已排除都卜勒的拍頻成立。~R≈cfb/(2S) applies only after Doppler is excluded.','線性啁啾、單一靜止目標及校正時間基準；此課僅虛擬光路。~Linear chirp, one static target and calibrated timing; only a virtual optical path is used.',['FFT 補零會增加實際物理解析度。~FFT zero-padding increases physical resolution.','運動目標單一拍頻一定只代表距離。~A moving target beat always represents range alone.','每個頻譜峰都必定是一個獨立實體。~Every spectral peak necessarily identifies a separate object.'],['lidar','coherent','opa'],[('a179','共用發射孔徑與相位校正。~Both share a transmit aperture and phase calibration.','光束轉向不能單獨提供距離與速度。~Beam steering alone does not provide range or velocity.','把方向誤差與啁啾誤差分別注入點雲。~Inject angle and chirp errors separately into a point cloud.'),('a178','兩課都使用本振混頻與平衡偵測。~Both use LO mixing and balanced detection.','光達的延遲與都卜勒是被估參數；通訊把相位變化解碼為資料。~Lidar estimates delay and Doppler; communications decode phase changes as data.','比較兩種接收鏈的時钟與線寬要求。~Compare timing and linewidth requirements in both receivers.')],subcategory='photonic-sensing-computing')

course('a181','表面感測、參考通道與檢出限~surface sensing, reference channels and detection limits','光學與表面~Optics and surface|流體與參考~Fluidics and references|校正與辨識~Calibration and discrimination|封裝與證據~Packaging and evidence',r'''
倏逝場感測~Evanescent-field sensing|表面附近折射率變化透過模態重疊改變共振，體相與表面結合可能同時作用。~Near-surface index changes shift resonance through modal overlap; bulk and surface binding can act together.|畫倏逝場及液體接觸區，分開列體相折射率和表面覆蓋變數。~Draw the evanescent field and fluid contact region, separating bulk index from surface coverage.
靈敏度與選擇性~Sensitivity versus selectivity|光學折射率靈敏度不等於生物分子選擇性，後者依賴辨識界面與對照。~Optical index sensitivity is not molecular selectivity, which depends on recognition interfaces and controls.|比較相同折射率變化的目標與非目標樣本，說明光學單獨無法分辨。~Compare target/nontarget samples with equal index changes and show why optics alone cannot distinguish them.
檢出限算例~Detection-limit example|以背景標準差除以斜率估計檢出限需固定訊號定義與校正範圍。~A noise-to-slope detection limit requires fixed signal definition and calibration range.|按算例保留單位，並分別報空白噪聲、斜率與所用倍數。~Retain units in the example and report blank noise, slope and the chosen multiplier separately.
參考微環~Reference microring|未功能化或不同探針參考通道可追蹤共同溫漂，但不一定共享所有非特異吸附。~Unfunctionalized or differently probed references track common drift but may not share all nonspecific adsorption.|比較主通道、參考通道及空白液體的時間曲線，不預設完全抵銷。~Compare sensing, reference and blank-fluid time traces without assuming perfect cancellation.
微流體交換~Microfluidic exchange|死體積、擴散與流速會改變到達表面的時間；反應曲線可能受傳質限制。~Dead volume, diffusion and flow affect arrival time; measured kinetics may be transport limited.|改變假想流速並檢查時間常數是否跟著變，而非直接擬合成分子速率。~Change hypothetical flow and check whether time constants change instead of calling them molecular rates directly.
表面覆蓋~Surface coverage|探針密度太高可能增加遮蔽與非特異吸附，訊號不是無限制正比探針數。~Excess probe density can increase steric blocking and nonspecific binding; signal is not unlimited linear probe scaling.|比較兩種表面覆蓋的目標與非目標對照，保留基線差異。~Compare target/nontarget controls at two coverages and retain baseline differences.
溫度與基線~Temperature and baseline|矽的熱光響應可能遠大於微小結合訊號，必須量測局部溫度或匹配參考。~Silicon thermo-optic shifts can exceed small binding signals; local temperature or matched references are needed.|先以無結合的液體做溫度掃描，再對照感測試驗。~Perform a temperature sweep with nonbinding fluid before comparing sensing traces.
氣泡與散射~Bubbles and scattering|氣泡可同時改變有效折射率、耦合和共振線形，不能視為一次高濃度事件。~Bubbles change index, coupling and lineshape together and are not simply high-concentration events.|同步比對流道影像、透射功率與線寬，標記氣泡區段。~Correlate channel images, transmission and linewidth and flag bubble intervals.
濃度校正~Concentration calibration|校正曲線應包含空白、已知濃度與獨立驗證樣本，不能只在訓練點評估。~Calibration needs blanks, known concentrations and independent validation, not only fitted points.|將一組濃度保留不參與擬合，報預測誤差和非線性範圍。~Withhold one concentration from fitting and report prediction error and nonlinear range.
重複性與漂移~Repeatability and drift|同一次量測的短期標準差不能代替跨日、跨晶片及跨批重複性。~Within-run standard deviation does not replace day, chip and lot reproducibility.|建立晶片、日期與操作者分層資料表，分開報各變異來源。~Build chip/day/operator hierarchical records and report separate variability sources.
封裝液密~Fluidic package sealing|液密、光耦合與電隔離需要共同驗證；沒有漏液不代表感測基線穩定。~Leak tightness, optical coupling and electrical isolation need joint validation; no leak does not guarantee stable baseline.|比較封裝前後共振、壓力保持與空白液循環後漂移。~Compare resonance, pressure hold and blank-fluid-cycle drift before/after packaging.
結論邊界~Interpretation boundary|研究感測訊號不等於臨床診斷效能；真實樣本基質和交叉反應需另驗證。~Research sensor response is not clinical diagnostic performance; real matrices and cross-reactivity need separate validation.|將可支持的光學結論與尚未驗證的生物或臨床結論分列。~Separate supported optical conclusions from unvalidated biological or clinical claims.
''','假設濃度校正斜率 0.20 nm/(mg/L)，空白波長標準差 0.002 nm，以 3σ/slope 估計 LOD=0.030 mg/L。此為自訂統計示例，不是任何生物標記的診斷門檻。~Assume calibration slope 0.20 nm/(mg/L) and blank wavelength SD 0.002 nm. A 3σ/slope estimate gives LOD=0.030 mg/L. This is a statistical teaching example, not a diagnostic cutoff for any biomarker.','局部線性模型 Δλ=S·C+b；參考扣除後仍需重新估背景變異。~Local linear model Δλ=S·C+b; re-estimate background variation after reference subtraction.','假設局部線性、穩定空白與指定噪聲統計；吸附飽和、基質效應不在算例內。~Assume local linearity, stable blanks and specified noise statistics; adsorption saturation and matrix effects are excluded.',['高折射率靈敏度就等於高度生物選擇性。~High index sensitivity equals high biological selectivity.','只要沒有漏液就能保證基線穩定。~No fluid leakage guarantees a stable baseline.','同次短期噪聲就完整代表跨批重複性。~Within-run noise fully represents cross-lot reproducibility.'],['bio','isipp','tap'],[('a175','感測微環也需要讀取共振與分離溫漂。~Sensing rings also need resonance readout and thermal-drift separation.','WDM 濾波追求穩定通道，感測器刻意讓特定界面響應外界。~WDM filters seek stable channels; sensors intentionally expose a responsive interface.','比较參考環與濾波鎖定環對外界擾動的處理。~Compare reference-sensor and filter-lock handling of external disturbances.'),('a182','兩課都需要空白、校正與檢出限。~Both need blanks, calibration and detection limits.','生物感測可能讀折射率或結合；中紅外讀吸收光譜以增加化學辨識。~Biosensing may read index or binding; mid-IR reads absorption spectra for chemical discrimination.','設計同樣濃度變化但不同辨識證據的兩個實驗。~Design two experiments with the same concentration change but different identification evidence.')],subcategory='photonic-sensing-computing')

course('a182','中紅外材料透明窗、吸收路徑與背景校正~mid-IR transparency windows, absorption paths and background calibration','材料與波段~Materials and wavelength|波導與取樣~Waveguides and sampling|光譜與校正~Spectra and calibration|封裝與驗收~Packaging and acceptance',r'''
波段與化學指紋~Wavelength and chemical fingerprint|中紅外分子吸收能提供化學資訊，但重疊譜線與背景會造成歧義。~Mid-IR molecular absorption carries chemical information, but overlapping lines and backgrounds create ambiguity.|選兩條可區分假想成分的吸收帶，另設無吸收參考帶。~Choose two bands distinguishing hypothetical species plus a nonabsorbing reference band.
材料透明窗~Material transparency window|核心、包覆、基板與黏著劑都有各自吸收窗；近紅外低損耗不能直接延伸到中紅外。~Core, cladding, substrate and adhesive have separate absorption windows; low near-IR loss does not automatically extend to mid-IR.|建立四種材料的波段適用表，將未知吸收列為待查資料。~Create wavelength-validity tables for all four materials and mark unknown absorption for measurement.
有效吸收長度~Effective absorption length|倏逝場只部分重疊樣本，因此有效吸收由模態重疊與實體長度共同決定。~Only part of the evanescent field overlaps the sample, so overlap and physical length jointly set absorption.|按算例比較重疊率與長度，不把整條波導視為全在樣本內。~Compare overlap and length in the example rather than placing the whole mode inside the sample.
波導散射~Waveguide scattering|長波長改變侷限、彎曲及散射機制，縮放幾何不保證保留原損耗。~Longer wavelengths change confinement, bending and scattering; geometric scaling need not preserve loss.|比較短直、長直與彎曲見證結構，分開萃取各項損失。~Compare short/long straight and bent witnesses to extract separate losses.
暴露與保護~Exposure and protection|提高樣本重疊可能增加污染與機械脆弱性，封裝需兼顧取樣與保護。~Increasing sample overlap may increase contamination and fragility; packaging must balance exposure and protection.|比較全覆蓋與開窗區的耦合、污染及可清潔性。~Compare fully clad and exposed sections for coupling, contamination and cleanability.
氣體或液體傳輸~Gas or liquid transport|樣本到波導的傳輸延遲與交換效率影響濃度讀值。~Transport delay and exchange efficiency affect concentration readout.|用濃度階躍的上升與下降曲線估計滯留，不直接等同光學反應時間。~Use concentration-step rise/fall curves to estimate retention rather than calling it optical response time.
吸收與基線~Absorption and baseline|來源功率、耦合和偵測器響應也隨波長改變，需用參考除去背景。~Source power, coupling and detector response vary with wavelength and require reference normalization.|量空白與樣本光譜後再求比值，保留暗訊號扣除順序。~Measure blank/sample spectra before forming ratios and retain dark-subtraction order.
吸光度定義~Absorbance definition|自然對數光學深度與十進吸光度差一個 ln10，混用會產生尺度錯誤。~Natural-log optical depth and base-10 absorbance differ by ln10; mixing them creates scale error.|以同一透射比同時計算兩種定義並標註。~Compute and label both definitions from the same transmission ratio.
偵測器背景~Detector background|中紅外偵測器的熱背景與暗電流會限制弱吸收量測。~Thermal background and detector dark current can limit weak-absorption measurements.|比较遮光、空白與樣本訊號的頻譜及時間波動。~Compare blocked, blank and sample signals in spectral and time domains.
多成分反算~Multispecies inversion|多成分吸收矩陣高度相似時，濃度反算對噪聲敏感。~Similar species spectra make concentration inversion noise sensitive.|比較兩組候選波段的矩陣條件數與保留樣本預測誤差。~Compare matrix conditioning and held-out prediction errors for two wavelength sets.
溫度與壓力~Temperature and pressure|光譜線形與材料折射率會隨溫壓變化，參考須與樣本條件匹配。~Lineshapes and material indices vary with temperature/pressure; references must match sample conditions.|在固定濃度下改溫度或壓力，確認校正是否誤報濃度變化。~Vary temperature or pressure at fixed concentration and test false concentration reports.
長期漂移~Long-term drift|表面沉積、封裝吸收與來源老化可能讓校正失效。~Surface deposits, package absorption and source aging can invalidate calibration.|規劃定期空白與已知標樣，分開可清潔漂移和不可逆損傷。~Plan periodic blanks and known standards, distinguishing cleanable drift from irreversible damage.
''','假設吸收係數 α=2 cm^-1、模態重疊 Γ=0.10、長度 L=1 cm，僅樣本吸收時 T=exp(-ΓαL)=exp(-0.2)=0.819；十進吸光度=-log10 T=0.0869。~Assume α=2 cm^-1, modal overlap Γ=0.10 and length L=1 cm. With sample absorption alone T=exp(-ΓαL)=0.819; base-10 absorbance is -log10 T=0.0869.','T=exp(-ΓαL)，背景波導損失需另計或由匹配空白消除。~T=exp(-ΓαL); background waveguide loss must be included separately or removed using a matched blank.','均勻濃度、弱耦合擾動與線性吸收；不代表某化學物質實測值。~Uniform concentration, weak modal perturbation and linear absorption; not measured values for a chemical.',['近紅外透明材料在所有中紅外波段也透明。~Near-IR-transparent materials are transparent throughout mid-IR.','自然對數光學深度等於十進吸光度。~Natural-log optical depth equals base-10 absorbance.','全部光功率都與外部樣本重疊。~All optical power overlaps the external sample.'],['mir','sin'],[('a181','共用樣本交換、空白對照與檢出限推論。~Both use sample exchange, blanks and detection-limit inference.','吸收光譜與表面結合的訊號機制不同。~Absorption spectra and surface binding use different signal mechanisms.','比较相同背景漂移下兩種訊號的參考設計。~Compare reference designs under the same background drift.'),('a152','低損耗波導有助增加有效作用長度。~Low-loss guides can increase interaction length.','中紅外透明窗與近紅外 SiN 規格不可直接互換。~Mid-IR transparency cannot be inferred directly from near-IR SiN specifications.','列核心、包覆及基板的波段限制。~List wavelength limits for core, cladding and substrate.')],subcategory='photonic-sensing-computing')

course('a183','微腔色散、非線性振盪與頻梳相干性~microresonator dispersion, nonlinear oscillation and comb coherence','腔體與材料~Cavity and materials|色散與泵浦~Dispersion and pumping|狀態與鎖定~States and locking|封裝與證據~Packaging and evidence',r'''
矽與氮化矽~Silicon versus silicon nitride|矽光子生態含不同材料；Si 與 SiN 的吸收、非線性與熱限制不能混用。~The silicon-photonics ecosystem includes distinct materials; Si and SiN absorption, nonlinearity and thermal limits are not interchangeable.|建立兩材料在選定波段的非線性與損失表，未知值不猜填。~Build material tables for the chosen band and leave unmeasured values unresolved.
腔增強~Cavity enhancement|高 Q 增強腔內場，但耦合、泵浦失諧及熱穩定性共同決定可用增強。~High Q enhances intracavity fields, but coupling, detuning and thermal stability set usable enhancement.|比較相同載入 Q、不同耦合比的入腔及輸出功率。~Compare intracavity and extracted powers for equal loaded Q but different coupling ratios.
模態間隔~Mode spacing|頻梳梳齒間隔常與腔 FSR 相關，但真正相干性不能由等間距光譜獨自證明。~Comb spacing often relates to cavity FSR, but an equally spaced spectrum alone does not prove coherence.|按算例求 FSR，再另列需量的射頻拍頻與相位雜訊。~Calculate FSR using the example and separately list required RF-beat and phase-noise measurements.
整合色散~Integrated dispersion|Dint 表示模頻偏離等間距的程度，號誌規約須明確。~Integrated dispersion measures departure from equally spaced modes and requires a defined sign convention.|從一組模頻扣除線性基準，畫殘差而非只看相鄰間距。~Subtract a linear baseline from mode frequencies and plot residuals, not only adjacent spacing.
四波混頻~Four-wave mixing|能量守恆與相位匹配共同約束新頻率產生；有非線性不代表所有梳齒都成長。~Energy conservation and phase matching jointly constrain new frequencies; nonlinearity alone does not grow every line.|標出兩泵浦光子與訊號、閒置頻率，核對頻率和及相位失配。~Mark pump, signal and idler frequencies and verify frequency sums and mismatch.
模式交叉~Mode crossings|不同模族耦合會擾動局部色散，可能促進或破壞某些梳狀態。~Coupled mode families perturb local dispersion and may help or disrupt particular comb states.|比較局部模頻偏移與光譜異常，避免以單一平滑多項式掩蓋交叉。~Correlate local frequency shifts with spectral anomalies rather than hiding crossings in a smooth fit.
泵浦失諧~Pump detuning|泵浦相對熱移共振的失諧是動態量，掃描方向與速度影響到達狀態。~Detuning from a thermally shifted resonance is dynamic; scan direction and speed affect the reached state.|比較正反向掃描的透射、梳功率與射頻雜訊。~Compare transmission, comb power and RF noise on forward/reverse scans.
狀態辨識~State identification|調變不穩定、混沌與孤子狀態不能只依光譜包絡命名。~Modulation-instability, chaotic and soliton states cannot be named from spectral envelopes alone.|要求時間或相關量測、低頻噪聲與重複啟動證據交叉確認。~Require temporal/correlation measurements, low-frequency noise and repeatable startup evidence.
梳齒功率~Per-line power|總梳功率不能代表每齒可用功率，泵浦殘留也可能占很大比例。~Total comb power does not give usable per-line power, and residual pump may dominate.|分別積分泵浦、有效梳齒和背景，附解析頻寬。~Integrate pump, useful lines and background separately with resolution bandwidth stated.
頻率穩定~Frequency stability|重複頻率與整體頻移需要不同鎖定量；短時窄線寬不等於長時穩定。~Repetition rate and common frequency offset need distinct controls; short linewidth does not imply long-term stability.|分別追蹤梳齒與拍頻的時間序列，報漂移和噪聲。~Track a comb line and beat frequency separately and report drift and noise.
封裝泵浦耦合~Packaged pump coupling|泵浦耦合漂移會改變腔內狀態，封裝需控制反射、偏振與熱路。~Pump-coupling drift changes intracavity states; packaging must control reflection, polarization and heat paths.|在保持源功率時擾動耦合與溫度，測狀態存活範圍。~Perturb coupling and temperature at fixed source power and measure state-survival range.
應用驗收~Application acceptance|通訊、量測與量子用途對相干性、功率平坦度及噪聲有不同要求。~Communication, metrology and quantum uses require different coherence, flatness and noise performance.|為一個選定用途列最差梳齒驗收，不以總頻寬取代全部指標。~Define worst-line acceptance for one application rather than replacing all metrics with total span.
''','假設環半徑 R=100 μm、ng=2，腔長 L=2πR=628.3 μm，FSR=c/(ngL)≈238.7 GHz。這只估線性模態間隔，不能由此聲稱已形成孤子。~Assume ring radius R=100 μm and ng=2. Length L=628.3 μm gives FSR≈238.7 GHz. This estimates linear mode spacing and does not establish soliton formation.','FSR≈c/(ngL)；Dint(μ)=ωμ−(ω0+D1μ) 需標明角頻率單位。~FSR≈c/(ngL); Dint(μ)=ωμ−(ω0+D1μ) requires angular-frequency units.','群折射率取常數的局部近似；泵浦、熱與非線性閾值不含於算例。~Local constant-group-index approximation; pump, thermal and nonlinear thresholds are excluded.',['等間距光譜即可證明全部梳齒相干。~Equally spaced spectra alone prove full comb coherence.','總梳功率就是每個梳齒的功率。~Total comb power equals every line power.','矽與氮化矽的非線性和吸收完全相同。~Silicon and silicon nitride have identical nonlinearity and absorption.'],['comb','sin'],[('a175','共用共振、耦合、熱漂移與調諧量測。~Both use resonance, coupling, drift and tuning measurements.','WDM 環通常在近線性濾波區；微梳刻意利用非線性且要辨識動態狀態。~WDM rings usually filter near-linearly; microcombs deliberately exploit nonlinearity and require state identification.','比較兩課相同 Q 下需額外量的動態證據。~Compare additional dynamic evidence needed at equal Q.'),('a184','四波混頻同時連結經典頻梳與自發光子對。~Four-wave mixing connects classical combs and spontaneous photon pairs.','高功率經典梳不是量子光源證明；後者需關聯與統計測試。~A high-power classical comb does not prove a quantum source; correlations and statistics are needed.','列相同光譜仍無法判斷的量子指標。~List quantum metrics that an identical spectrum cannot establish.')],subcategory='photonic-sensing-computing')

course('a184','光子對、光譜純度與符合計數~photon pairs, spectral purity and coincidence counting','光源與模式~Sources and modes|濾波與封裝~Filtering and packaging|統計與干涉~Statistics and interference|擴展與驗收~Scaling and acceptance',r'''
自發與受激~Spontaneous versus stimulated processes|自發四波混頻可產生相關光子對；經典增益或明亮光譜本身不是量子證據。~Spontaneous four-wave mixing can create correlated pairs; classical gain or bright spectra alone are not quantum evidence.|將平均功率、單光子計數與符合計數分為三種不同觀察。~Separate mean power, singles and coincidences as three different observations.
能量與相位匹配~Energy and phase matching|二泵浦頻率和等於訊號與閒置頻率和，仍需檢查模式及色散匹配。~Two-pump frequency sum equals signal-plus-idler sum, but modes and dispersion must also match.|畫頻率與模態配對，排除只符合能量而相位嚴重失配的案例。~Map frequency/mode pairs and reject energy-matched but strongly phase-mismatched cases.
偵測效率~Detection efficiency|觀測符合率受兩臂全部傳輸與偵測效率相乘限制，不能直接當產生率。~Observed coincidence rate is limited by both arms' transmission/detection efficiencies and is not the generation rate.|按算例計算單臂效率與符合率，逐項列耦合、濾波和偵測器損失。~Calculate arm efficiencies and coincidences in the example, listing coupling, filtering and detector losses.
泵浦抑制~Pump rejection|殘留泵浦與非目標散射可淹沒稀少光子訊號，濾波也會損失有效光子。~Residual pump and unwanted scattering can overwhelm rare photons; filtering also loses useful photons.|分開量泵浦抑制、訊號通過率與偵測器暗計數。~Measure pump suppression, signal transmission and detector dark counts separately.
光譜關聯~Spectral correlations|訊號與閒置光子的聯合光譜關聯影響 heralded 純度；窄單臂光譜不足以證明純度。~Joint spectral correlations affect heralded purity; a narrow single-arm spectrum does not prove purity.|畫聯合光譜而非兩條各自光譜，標出儀器解析度及相位資訊缺口。~Plot a joint spectrum rather than two separate spectra, marking resolution and missing phase information.
偏振與時間模式~Polarization and temporal modes|光子可區分性包含偏振、時間、頻率與空間模式，不只中心波長。~Distinguishability includes polarization, time, frequency and spatial mode, not only center wavelength.|逐一改變延遲或偏振，預測干涉可見度的變化。~Vary delay or polarization individually and predict interference visibility changes.
符合視窗~Coincidence window|較寬時間視窗增加真符合收集也增加偶然符合，需報完整時間直方圖。~A wider coincidence window captures true events but also accidentals; report the full timing histogram.|比較三種視窗的原始符合、旁窗背景及淨符合。~Compare raw, side-window background and net coincidences for three windows.
CAR 定義~CAR definition|符合對偶然比有不同慣例，須說清是原始符合或扣背景後符合除以偶然。~Coincidence-to-accidental ratio conventions differ; state whether the numerator is raw or background-subtracted.|以同一組計數算兩種慣例，保留積分時間與泊松誤差。~Compute both conventions from the same counts, retaining integration time and Poisson error.
多光子事件~Multipair events|提高泵浦可增加產生率但也增加多對事件，亮度與單光子品質存在取捨。~Higher pump raises generation but also multipair events, trading brightness against single-photon quality.|掃泵浦並同時比較 heralded 統計與符合率，不只最大化計數。~Sweep pump and compare heralded statistics with coincidences rather than maximizing counts alone.
雙光子干涉~Two-photon interference|Hong–Ou–Mandel 凹陷的可見度受可區分性、雜訊及分光比影響。~Hong-Ou-Mandel visibility depends on distinguishability, noise and splitter ratio.|保留原始及扣背景可見度，掃延遲並檢查遠離重疊時的基線。~Retain raw/background-subtracted visibility, scan delay and check the far-delay baseline.
封裝與相位穩定~Packaging and phase stability|光纖漂移、應力與溫度會使多路量子干涉失配，即使總通光率穩定。~Fiber drift, stress and temperature can spoil multipath interference even at stable throughput.|同步追蹤參考相位、溫度與干涉可見度，區分損失與相位失配。~Track reference phase, temperature and visibility together to distinguish loss from phase mismatch.
可擴展性證據~Scaling evidence|多源同步需同時滿足可區分性、損耗和時序；单一最佳源不代表可擴展處理器。~Multiple sources need simultaneous indistinguishability, low loss and timing; one best source is not a scalable processor.|比較兩顆獨立源的干涉與跨晶片重複性，列尚未驗證的整合項。~Compare interference from two independent sources and cross-chip repeatability, listing unverified integration items.
''','假設每秒產生 10^6 對，兩臂總效率皆 0.10，理想真符合率=10^6×0.1×0.1=10^4/s。若原始符合 11000/s、偶然 1000/s，raw CAR=11，net CAR=10；需注明慣例。~Assume 10^6 pairs/s and total efficiency 0.10 per arm. Ideal true coincidences are 10^4/s. With raw coincidences 11000/s and accidentals 1000/s, raw CAR=11 and net CAR=10; state the convention.','Ctrue≈Rpairηsηi；獨立泊松計數的標準差約 √N，不直接套於強相關或校正後資料。~Ctrue≈Rpairηsηi; independent Poisson counts have SD≈√N, not automatically valid for strongly correlated or corrected data.','低多對、獨立損失及無死時間近似；未包含濾波純度與偵測飽和。~Low multipair, independent-loss and negligible-dead-time assumptions; filtering purity and detector saturation are excluded.',['觀測符合率一定等於光子對產生率。~Observed coincidences always equal pair generation rate.','只看明亮光譜就能證明量子光。~A bright spectrum alone proves quantum light.','提高泵浦只增加好處而不增加多對事件。~Higher pump adds benefits without increasing multipair events.'],['quantum','comb','tap'],[('a183','兩課共用色散、腔增強與四波混頻。~Both use dispersion, cavity enhancement and four-wave mixing.','自發量子光需符合與干涉證據，經典頻梳重點是功率、相位雜訊與頻率穩定。~Spontaneous quantum light needs coincidences/interference; classical combs emphasize power, phase noise and frequency stability.','把相同頻率圖換成兩種不同量測鏈。~Turn the same frequency diagram into two different measurement chains.'),('a177','可編程網格可操作光子路徑與相位。~Programmable meshes manipulate photon paths and phases.','量子應用對損失、多光子雜訊與可區分性有額外限制。~Quantum use adds constraints on loss, multiphoton noise and distinguishability.','以一個 2×2 網格做原創雙光子干涉概念圖。~Draw an original two-photon-interference concept using a 2×2 mesh.')],subcategory='photonic-sensing-computing')

